    appId: import.meta.env.VITE_FIREBASE_APP_ID
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const db = getFirestore(app);
export const storage = getStorage(app);
const analytics = getAnalytics(app);
import { getFunctions } from "firebase/functions";
export const functions = getFunctions(app);

// src/pages/Configuracion.jsx
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Settings, Lock, Save, CheckSquare, Square, Loader2, LogIn, LogOut, TriangleAlert } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { db } from '../firebaseConfig';
import { fetchLicenseStatus, applyNewLicenseToken } from '../services/licenseService';

// ─── Definición de todos los campos configurables ────────────────────────────
const FIELD_GROUPS = [
    {
        group: '1. Identificación Básica',
        fields: [
            { key: 'documentoIdentidad', label: 'Documento de identidad' },
            { key: 'fechaNacimiento', label: 'Fecha de nacimiento' },
            { key: 'fechaIngreso', label: 'Fecha de ingreso' },
            { key: 'infoBancaria', label: 'Información bancaria' },
            { key: 'licenciaConducir', label: 'Licencia de conducir' },
            { key: 'tallaUniforme', label: 'Talla de uniformes' },
            { key: 'tallaCalzado', label: 'Talla de calzado' },
            { key: 'alergias', label: 'Alergias / condiciones médicas' },
            { key: 'estadoCivil', label: 'Estado civil' },
            { key: 'hijos', label: 'Hijos y edades' },
            { key: 'grupoSanguineo', label: 'Grupo sanguíneo' },
            { key: 'eps', label: 'EPS' },
            { key: 'arl', label: 'ARL' },
        ],
    },
    {
        group: '2. Contacto y Ubicación',
        fields: [
            { key: 'direccion', label: 'Dirección de residencia' },
            { key: 'telefono', label: 'Teléfono personal' },
            { key: 'correoPersonal', label: 'Correo electrónico personal (≠ login)' },
            { key: 'contactoEmergencia', label: 'Contacto de emergencia' },
        ],
    },
    {
        group: '3. Formación y Perfil Profesional',
        fields: [
            { key: 'nivelEducativo', label: 'Nivel educativo' },
            { key: 'idiomas', label: 'Idiomas y nivel' },
        ],
    },
];

// Estado por defecto: todos desactivados para los campos de usuario, y defaults para storage
const DEFAULT_CONFIG = {
    ...Object.fromEntries(FIELD_GROUPS.flatMap(g => g.fields.map(f => [f.key, false]))),
    storage_saveAsistencia: true,
    storage_saveIncidentes: true,
    storage_retentionAsistencia: 90,
    storage_retentionIncidentes: 540,
    // defaults calculo tiempo
    calc_rounding: false,
    calc_roundingMins: 15,
    calc_lunch: false,
    calc_lunchMins: 60,
    // defaults etiquetas botones
    ui_labelEntry: "Registrar Entrada",
    ui_labelExit: "Registrar Salida",
    ui_labelIncident: "Reportar Novedad",
    // defaults seguridad
    security_liveness: true,
    security_faceThreshold: 0.63,
};

export default function Configuracion() {
    const [config, setConfig] = useState(DEFAULT_CONFIG);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [savedOk, setSavedOk] = useState(false);
    const [licenseStatus, setLicenseStatus] = useState(null);
    const [licenseInput, setLicenseInput] = useState('');
    const [savingLicense, setSavingLicense] = useState(false);
    const [licenseError, setLicenseError] = useState('');
    const navigate = useNavigate();
    const { adminAccess, currentUser } = useAuth();

    useEffect(() => {
        if (!adminAccess['/configuracion']) {
            navigate('/login');
            return;
        }
        loadConfig();
    }, [adminAccess]);

    const loadConfig = async () => {
        try {
            const snap = await getDoc(doc(db, 'settings', 'employeeFields'));
            if (snap.exists()) {
                // Mezclamos los datos base con los que vengan de la BD para que tome en cuenta los nuevos defaults (storage_*)
                setConfig(prev => ({ ...prev, ...snap.data() }));
            } else {
                // Primer uso: inicializamos la BD con los defaults
                await setDoc(doc(db, 'settings', 'employeeFields'), DEFAULT_CONFIG);
            }

            // Cargar estado de la Licencia
            const licData = await fetchLicenseStatus();
            setLicenseStatus(licData);

        } catch (err) {
            console.error('Error cargando configuración:', err);
        } finally {
            setLoading(false);
        }
    };

    const toggle = (key) => {
        setConfig(prev => ({ ...prev, [key]: !prev[key] }));
        setSavedOk(false);
    };

    const handleTextChange = (key, value) => {
        setConfig(prev => ({ ...prev, [key]: value }));
        setSavedOk(false);
    };

    const handleNumberChange = (key, value, maxVal = 730) => {
        const val = parseInt(value, 10);
        setConfig(prev => ({ ...prev, [key]: isNaN(val) ? 1 : val > maxVal ? maxVal : val < 1 ? 1 : val }));
        setSavedOk(false);
    };

    const handleFloatChange = (key, value, maxVal = 1.0, minVal = 0.0) => {
        const val = parseFloat(value);
        setConfig(prev => ({ ...prev, [key]: isNaN(val) ? minVal : val > maxVal ? maxVal : val < minVal ? minVal : val }));
        setSavedOk(false);
    };

    const saveConfig = async () => {
        setSaving(true);
        try {
            await setDoc(doc(db, 'settings', 'employeeFields'), config);
            setSavedOk(true);
            setTimeout(() => setSavedOk(false), 3000);
        } catch (err) {
            console.error('Error guardando configuración:', err);
            alert('Error al guardar. Inténtalo de nuevo.');
        } finally {
            setSaving(false);
        }
    };

    const handleUpdateLicense = async () => {
        if (!licenseInput.trim()) return;
        setSavingLicense(true);
        setLicenseError('');
        try {
            const result = await applyNewLicenseToken(licenseInput);
            setLicenseStatus({ rawToken: licenseInput, decoded: result });
            setLicenseInput('');
            alert("Licencia actualizada exitosamente.");
        } catch (error) {
            setLicenseError(error.message || "Token inválido.");
        } finally {
            setSavingLicense(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B]">
                <Loader2 size={40} className="text-purple-600 animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B] p-6">
            <div className="max-w-3xl mx-auto">
                {/* Header */}
                <div className="flex justify-between items-center mb-8">
                    <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2">
                        <Settings size={30} className="text-purple-600" />
                        Configuración
                        <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-mono ml-2 border border-gray-200">v{import.meta.env.VITE_APP_VERSION}</span>
                    </h1>
                    <div className="flex gap-3">
                        <button
                            onClick={() => navigate('/cambiar-clave-admin')}
                            className="px-4 py-2 bg-yellow-500 text-white rounded-lg hover:bg-yellow-600 font-bold transition flex items-center gap-2"
                        >
                            <Lock size={18} />
                            Cambiar Contraseña
                        </button>
                        <button
                            onClick={() => navigate('/dashboard')}
                            className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 border border-gray-300"
                        >
                            Volver
                        </button>
                    </div>
                </div>

                {/* ─── GESTIÓN DE LICENCIA ─── */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-indigo-500">
                    <h2 className="text-xl font-bold text-indigo-800 mb-2">Estado de la Licencia</h2>
                    <p className="text-sm text-gray-600 mb-4">
                        Información de su plan contratado y método para actualizar la suscripción.
                    </p>

                    {licenseStatus && licenseStatus.decoded ? (
                        <div className={`p-4 rounded-xl border mb-4 text-sm ${licenseStatus.decoded.isExpired ? 'bg-red-50 border-red-200 text-red-800' : 'bg-emerald-50 border-emerald-200 text-emerald-800'}`}>
                            {licenseStatus.decoded.isExpired && <p className="font-bold text-red-600 mb-2 flex items-center gap-2">⚠️ SU LICENCIA HA EXPIRADO</p>}
                            <div className="grid grid-cols-2 gap-2">
                                <div><b className="opacity-70">Límite contratado:</b> {licenseStatus.decoded.maxEmployees} <span className="text-xs opacity-60">(+{licenseStatus.decoded.bufferPercentage}% de cortesía)</span></div>
                                <div><b className="opacity-70">Válida hasta:</b> {licenseStatus.decoded.expirationDate}</div>
                                <div className="col-span-2 mt-2 pt-2 border-t border-black border-opacity-10">
                                    <b className="opacity-70">Proveedor de Software:</b> {licenseStatus.decoded.providerName} <br />
                                    <b className="opacity-70">Contacto (Soporte/Renovación):</b> {licenseStatus.decoded.providerPhone}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="p-4 bg-yellow-50 text-yellow-800 rounded-xl border border-yellow-200 mb-4 text-sm">
                            ⚠️ No hay una licencia válida o el código está corrupto. Contacte a su proveedor.
                        </div>
                    )}

                    <div className="mt-4">
                        <label className="block text-xs font-bold text-indigo-800 opacity-80 mb-1">Cargar nuevo código de licencia</label>
                        <div className="flex gap-2">
                            <input
                                type="text"
                                value={licenseInput}
                                onChange={(e) => setLicenseInput(e.target.value)}
                                placeholder="Pegue el código cifrado aquí..."
                                className="flex-1 px-3 py-2 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 font-mono text-xs"
                            />
                            <button
                                onClick={handleUpdateLicense}
                                disabled={savingLicense || !licenseInput}
                                className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition text-sm font-bold flex items-center gap-2"
                            >
                                {savingLicense ? <Loader2 size={16} className="animate-spin" /> : 'Activar Código'}
                            </button>
                        </div>
                        {licenseError && <p className="text-red-500 text-xs mt-1">{licenseError}</p>}
                    </div>
                </div>

                {/* ─── GESTIÓN DE ALMACENAMIENTO DE FOTOS ─── */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-blue-500">
                    <h2 className="text-xl font-bold text-blue-800 mb-2">Almacenamiento de Evidencias (Fotos)</h2>
                    <p className="text-sm text-gray-600 mb-4">
                        Configura si el sistema guardará de forma permanente las fotos al momento de entrar o si solo verificará el rostro sin guardar archivos pesados. Además, define el tiempo (en días) antes de que se borren y eliminen permanentemente.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* ASISTENCIA */}
                        <div className="space-y-3 bg-blue-50 p-4 rounded-xl border border-blue-100">
                            <h3 className="font-bold text-blue-700">Modo Asistencia</h3>
                            <button
                                onClick={() => toggle('storage_saveAsistencia')}
                                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                    ${config.storage_saveAsistencia !== false
                                        ? 'border-blue-500 bg-white text-blue-800'
                                        : 'border-gray-300 bg-gray-100 text-gray-400 opacity-60'}`}
                            >
                                <span className="flex items-center gap-2">
                                    {config.storage_saveAsistencia !== false
                                        ? <CheckSquare size={20} className="text-blue-600" />
                                        : <Square size={20} />}
                                    Guardar fotos asistencia
                                </span>
                            </button>

                            <div className="flex flex-col gap-1">
                                <label className="text-xs font-bold text-blue-800 opacity-80">Días de retención</label>
                                <input
                                    type="number"
                                    min="1" max="730"
                                    disabled={config.storage_saveAsistencia === false}
                                    value={config.storage_retentionAsistencia ?? 3}
                                    onChange={(e) => handleNumberChange('storage_retentionAsistencia', e.target.value)}
                                    className="px-3 py-2 border border-blue-200 rounded-lg focus:ring-2 focus:ring-blue-500 disabled:bg-gray-200 disabled:opacity-50"
                                />
                            </div>
                        </div>

                        {/* INCIDENTES */}
                        <div className="space-y-3 bg-orange-50 p-4 rounded-xl border border-orange-100">
                            <h3 className="font-bold text-orange-700">Modo Incidentes</h3>
                            <button
                                onClick={() => toggle('storage_saveIncidentes')}
                                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                    ${config.storage_saveIncidentes !== false
                                        ? 'border-orange-500 bg-white text-orange-800'
                                        : 'border-gray-300 bg-gray-100 text-gray-400 opacity-60'}`}
                            >
                                <span className="flex items-center gap-2">
                                    {config.storage_saveIncidentes !== false
                                        ? <CheckSquare size={20} className="text-orange-600" />
                                        : <Square size={20} />}
                                    Guardar fotos incidentes
                                </span>
                            </button>

                            <div className="flex flex-col gap-1">
                                <label className="text-xs font-bold text-orange-800 opacity-80">Días de retención</label>
                                <input
                                    type="number"
                                    min="1" max="730"
                                    disabled={config.storage_saveIncidentes === false}
                                    value={config.storage_retentionIncidentes ?? 18}
                                    onChange={(e) => handleNumberChange('storage_retentionIncidentes', e.target.value)}
                                    className="px-3 py-2 border border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-500 disabled:bg-gray-200 disabled:opacity-50"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* ─── GESTIÓN DE CÁLCULO DE HORAS ─── */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-teal-500">
                    <h2 className="text-xl font-bold text-teal-800 mb-2">Cálculo de Tiempo Laborado</h2>
                    <p className="text-sm text-gray-600 mb-4">
                        Configura el redondeo de entradas/salidas y el descuento automático de tiempo de almuerzo aplicable únicamente a turnos de más de 8 horas.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* REDONDEO */}
                        <div className="space-y-3 bg-teal-50 p-4 rounded-xl border border-teal-100">
                            <h3 className="font-bold text-teal-700">Redondeo de Horas</h3>
                            <button
                                onClick={() => toggle('calc_rounding')}
                                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                    ${config.calc_rounding !== false
                                        ? 'border-teal-500 bg-white text-teal-800'
                                        : 'border-gray-300 bg-gray-100 text-gray-400 opacity-60'}`}
                            >
                                <span className="flex items-center gap-2">
                                    {config.calc_rounding !== false ? <CheckSquare size={20} className="text-teal-600" /> : <Square size={20} />}
                                    Activar redondeo cercano
                                </span>
                            </button>
                            <p className="text-xs text-teal-700 opacity-80 leading-tight">Ejemplo: si es 15min, ingresar a las 07:58 se redondeará automáticamente a las 08:00 para el reporte detallado.</p>
                            <div className="flex flex-col gap-1">
                                <label className="text-xs font-bold text-teal-800 opacity-80">Fracción en Minutos</label>
                                <input
                                    type="number"
                                    min="1" max="60"
                                    disabled={config.calc_rounding === false}
                                    value={config.calc_roundingMins ?? 15}
                                    onChange={(e) => handleNumberChange('calc_roundingMins', e.target.value)}
                                    className="px-3 py-2 border border-teal-200 rounded-lg focus:ring-2 focus:ring-teal-500 disabled:bg-gray-200 disabled:opacity-50"
                                />
                            </div>
                        </div>

                        {/* ALMUERZO */}
                        <div className="space-y-3 bg-indigo-50 p-4 rounded-xl border border-indigo-100">
                            <h3 className="font-bold text-indigo-700">Descuento de Almuerzo</h3>
                            <button
                                onClick={() => toggle('calc_lunch')}
                                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                    ${config.calc_lunch !== false
                                        ? 'border-indigo-500 bg-white text-indigo-800'
                                        : 'border-gray-300 bg-gray-100 text-gray-400 opacity-60'}`}
                            >
                                <span className="flex items-center gap-2">
                                    {config.calc_lunch !== false ? <CheckSquare size={20} className="text-indigo-600" /> : <Square size={20} />}
                                    Descontar automáticamente
                                </span>
                            </button>
                            <p className="text-xs text-indigo-700 opacity-80 leading-tight">Solo aplicará si el empleado registra un tiempo laborado superior a 8 horas.</p>
                            <div className="flex flex-col gap-1">
                                <label className="text-xs font-bold text-indigo-800 opacity-80">Tiempo a descontar (Minutos)</label>
                                <input
                                    type="number"
                                    min="1" max="180"
                                    disabled={config.calc_lunch === false}
                                    value={config.calc_lunchMins ?? 60}
                                    onChange={(e) => handleNumberChange('calc_lunchMins', e.target.value, 180)}
                                    className="px-3 py-2 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-gray-200 disabled:opacity-50"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* ─── GESTIÓN DE SEGURIDAD ─── */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-emerald-500">
                    <h2 className="text-xl font-bold text-emerald-800 mb-2">Seguridad y Validaciones</h2>
                    <p className="text-sm text-gray-600 mb-4">
                        Configura las opciones de seguridad al momento de registrar asistencia.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* FACE RECOGNITION THRESHOLD */}
                        <div className="col-span-1 md:col-span-2 space-y-3 bg-blue-50 p-4 rounded-xl border border-blue-100">
                            <h3 className="font-bold text-blue-700">Sensibilidad del Reconocimiento Facial</h3>
                            <p className="text-sm text-blue-800 opacity-90 mb-2">
                                Ajusta qué tan rigurosa es la comparación del rostro actual contra la foto registrada. <br />
                                <span className="font-bold">Valor actual: {config.security_faceThreshold ?? 0.63}</span>
                            </p>

                            <input
                                type="range"
                                min="0.40"
                                max="0.80"
                                step="0.01"
                                value={config.security_faceThreshold ?? 0.63}
                                onChange={(e) => handleFloatChange('security_faceThreshold', e.target.value, 0.80, 0.40)}
                                className="w-full h-2 bg-blue-200 rounded-lg appearance-none cursor-pointer"
                            />

                            <div className="flex justify-between text-xs text-blue-600 font-bold mt-1">
                                <span>0.40 (Más estricto)</span>
                                <span>0.60</span>
                                <span>0.80 (Menos estricto)</span>
                            </div>

                            <div className="mt-2 p-3 rounded-xl text-sm transition-colors duration-300 border" style={{
                                backgroundColor: (config.security_faceThreshold ?? 0.63) < 0.56 ? '#fef2f2' : (config.security_faceThreshold ?? 0.63) <= 0.68 ? '#fdf8e6' : '#fef2f2',
                                color: (config.security_faceThreshold ?? 0.63) < 0.56 ? '#991b1b' : (config.security_faceThreshold ?? 0.63) <= 0.68 ? '#854d0e' : '#991b1b',
                                borderColor: (config.security_faceThreshold ?? 0.63) < 0.56 ? '#fecaca' : (config.security_faceThreshold ?? 0.63) <= 0.68 ? '#fef08a' : '#fecaca'
                            }}>
                                {(config.security_faceThreshold ?? 0.63) < 0.56 && <b>🔴 MUY ESTRICTO:</b>}
                                {(config.security_faceThreshold ?? 0.63) >= 0.56 && (config.security_faceThreshold ?? 0.63) <= 0.68 && <b>🟡 EQUILIBRADO (Recomendado):</b>}
                                {(config.security_faceThreshold ?? 0.63) > 0.68 && <b>🔴 PERMISIVO:</b>}

                                {(config.security_faceThreshold ?? 0.63) < 0.56 && " Solo aceptará coincidencias casi perfectas (buena luz, mismo ángulo). Puede generar rechazos falsos constantemente."}
                                {(config.security_faceThreshold ?? 0.63) >= 0.56 && (config.security_faceThreshold ?? 0.63) <= 0.68 && " El sistema acepta variaciones normales de luz o pequeños cambios angulares manteniendo alta seguridad contra suplantaciones."}
                                {(config.security_faceThreshold ?? 0.63) > 0.68 && " Mayor probabilidad de aceptar a personas con rasgos similares. Reduce la seguridad del sistema."}
                            </div>
                        </div>

                        {/* LIVENESS DETECTION */}
                        <div className="space-y-3 bg-emerald-50 p-4 rounded-xl border border-emerald-100">
                            <h3 className="font-bold text-emerald-700">Prueba de Vida (Movimiento de Cabeza)</h3>
                            <button
                                onClick={() => toggle('security_liveness')}
                                className={`w-full flex items-center justify-between px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                    ${config.security_liveness !== false
                                        ? 'border-emerald-500 bg-white text-emerald-800'
                                        : 'border-gray-300 bg-gray-100 text-gray-400 opacity-60'}`}
                            >
                                <span className="flex items-center gap-2">
                                    {config.security_liveness !== false
                                        ? <CheckSquare size={20} className="text-emerald-600" />
                                        : <Square size={20} />}
                                    Requerir girar la cabeza
                                </span>
                            </button>
                            <p className="text-xs text-emerald-700 opacity-80 leading-tight">
                                {config.security_liveness !== false
                                    ? "Activo: Se pedirá girar la cabeza para evitar el uso de fotos falsas."
                                    : "⚠️ Inactivo: Los empleados podrán registrar la asistencia tomando la foto manualmente sin comprobar movimiento."}
                            </p>
                        </div>
                    </div>
                </div>

                {/* ─── GESTIÓN DE ETIQUETAS DE BOTONES ─── */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-purple-600 overflow-hidden relative">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-purple-50 rounded-full -mr-16 -mt-16 opacity-50"></div>
                    <h2 className="text-xl font-bold text-purple-800 mb-2 relative">Personalización de Botones</h2>
                    <p className="text-sm text-gray-600 mb-6 relative">
                        Cambia los textos de la pantalla principal para que sean más amigables con el empleado.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 relative">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-purple-700 flex items-center gap-1">
                                <LogIn size={14} /> Etiqueta Entrada
                            </label>
                            <input
                                type="text"
                                placeholder="Ej: ¡Hola! Ya llegué"
                                value={config.ui_labelEntry || ""}
                                onChange={(e) => handleTextChange('ui_labelEntry', e.target.value)}
                                className="w-full px-3 py-2 border border-purple-200 rounded-lg focus:ring-2 focus:ring-purple-500 shadow-sm text-sm"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-red-700 flex items-center gap-1">
                                <LogOut size={14} /> Etiqueta Salida
                            </label>
                            <input
                                type="text"
                                placeholder="Ej: ¡Hasta mañana!"
                                value={config.ui_labelExit || ""}
                                onChange={(e) => handleTextChange('ui_labelExit', e.target.value)}
                                className="w-full px-3 py-2 border border-red-200 rounded-lg focus:ring-2 focus:ring-red-500 shadow-sm text-sm"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-orange-700 flex items-center gap-1">
                                <TriangleAlert size={14} /> Etiqueta Novedad
                            </label>
                            <input
                                type="text"
                                placeholder="Ej: Algo ocurrió..."
                                value={config.ui_labelIncident || ""}
                                onChange={(e) => handleTextChange('ui_labelIncident', e.target.value)}
                                className="w-full px-3 py-2 border border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-500 shadow-sm text-sm"
                            />
                        </div>
                    </div>
                </div>

                {/* Campos siempre activos */}
                <div className="bg-purple-50 border border-purple-200 rounded-xl p-4 mb-6 mt-8">
                    <p className="text-sm text-purple-700 font-medium">
                        🔒 <strong>Campos obligatorios (siempre activos):</strong> Nombre, Apellido y Correo de sistema — necesarios para crear el usuario de login.
                    </p>
                </div>

                {/* Secciones de campos configurables (Perfiles Empleado) */}
                {FIELD_GROUPS.map(({ group, fields }) => (
                    <div key={group} className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-purple-500">
                        <h2 className="text-xl font-bold text-purple-700 mb-4">{group}</h2>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {fields.map(({ key, label }) => (
                                <button
                                    key={key}
                                    onClick={() => toggle(key)}
                                    className={`flex items-center gap-3 px-4 py-3 rounded-lg border-2 text-left transition font-medium text-sm
                                        ${config[key]
                                            ? 'border-purple-500 bg-purple-50 text-purple-800'
                                            : 'border-gray-200 bg-gray-50 text-gray-500 hover:border-purple-300'}`}
                                >
                                    {config[key]
                                        ? <CheckSquare size={20} className="text-purple-600 shrink-0" />
                                        : <Square size={20} className="text-gray-400 shrink-0" />}
                                    {label}
                                </button>
                            ))}
                        </div>
                    </div>
                ))}

                {/* Botón Guardar */}
                <div className="flex justify-end gap-4 mt-2 mb-12">
                    {savedOk && (
                        <span className="text-green-600 font-medium flex items-center gap-1">
                            ✅ Configuración guardada exitosamente
                        </span>
                    )}
                    <button
                        onClick={saveConfig}
                        disabled={saving}
                        className="px-6 py-3 bg-purple-600 text-white font-bold rounded-lg hover:bg-purple-700 disabled:bg-gray-400 transition flex items-center gap-2 shadow-2xl"
                    >
                        {saving ? <Loader2 size={20} className="animate-spin" /> : <Save size={20} />}
                        {saving ? 'Guardando...' : 'Guardar Configuración'}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { useAuth } from '../contexts/AuthContext';
import { addWatermarkToImage, fetchServerTime, fetchLocationName } from '../utils/watermark';
import { db } from '../firebaseConfig';
import { collection, addDoc, query, where, getDocs, serverTimestamp, doc, getDoc } from 'firebase/firestore';
import { Camera, MapPin, CheckCircle, LogOut, LogIn, UserCheck, ShieldAlert, TriangleAlert } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import * as faceapi from '@vladmandic/face-api';
import { uploadPhoto } from '../services/storageService';
import { fetchLicenseStatus } from '../services/licenseService';

export default function Dashboard() {
    const { currentUser, logout } = useAuth();
    const navigate = useNavigate();
    // Refs for Native Camera
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const streamRef = useRef(null);
    const livenessIntervalRef = useRef(null);
    const modeRef = useRef(null);
    const isLivenessRunningRef = useRef(false);

    const [mode, setMode] = useState(null); // 'entry', 'exit', 'incident'
    const [allowedActions, setAllowedActions] = useState({ entry: true, exit: true });
    const [loadingState, setLoadingState] = useState(true);
    const [incidentDescription, setIncidentDescription] = useState(''); // Descripción de la novedad
    const [step, setStep] = useState('idle'); // idle, camera, processing, success
    const [statusMessage, setStatusMessage] = useState('');
    const [isCapturing, setIsCapturing] = useState(false);
    const [modelsLoaded, setModelsLoaded] = useState(false);
    const [savedDescriptor, setSavedDescriptor] = useState(null);
    const [faceVerified, setFaceVerified] = useState(false);
    const [verifyingFace, setVerifyingFace] = useState(false);
    const [faceError, setFaceError] = useState('');
    const [cameraReady, setCameraReady] = useState(false);
    // Liveness detection states
    const [blinkCount, setBlinkCount] = useState(0);
    const [autoCapturePending, setAutoCapturePending] = useState(false);
    const blinkCountRef = useRef(0);
    const eyeClosedRef = useRef(false);
    const [deferredPrompt, setDeferredPrompt] = useState(null);
    const [showInstallBtn, setShowInstallBtn] = useState(false);
    const [isIOS, setIsIOS] = useState(false);
    const [isStandalone, setIsStandalone] = useState(false);
    const [storageSettings, setStorageSettings] = useState({
        storage_saveAsistencia: true,
        storage_saveIncidentes: true,
        security_liveness: true
    });
    const [isLicenseValid, setIsLicenseValid] = useState(true);
    const [buttonLabels, setButtonLabels] = useState({
        entry: "Registrar Entrada",
        exit: "Registrar Salida",
        incident: "Reportar Novedad"
    });
    const [faceThreshold, setFaceThreshold] = useState(0.63);

    useEffect(() => {
        // Detectar si ya está instalada
        if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
            setIsStandalone(true);
        }

        // Detectar iOS
        const userAgent = window.navigator.userAgent.toLowerCase();
        if (userAgent.includes('iphone') || userAgent.includes('ipad') || userAgent.includes('ipod')) {
            setIsIOS(true);
        }

        window.addEventListener('beforeinstallprompt', (e) => {
            e.preventDefault();
            setDeferredPrompt(e);
            setShowInstallBtn(true);
        });
    }, []);

    const handleInstallClick = async () => {
        if (!deferredPrompt) return;
        deferredPrompt.prompt();
        const { outcome } = await deferredPrompt.userChoice;
        if (outcome === 'accepted') {
            setShowInstallBtn(false);
        }
        setDeferredPrompt(null);
    };

    const clearAppCache = async () => {
        if (window.confirm("¿Deseas limpiar la memoria de la aplicación? Esto forzará la carga de la versión más reciente.")) {
            if ('serviceWorker' in navigator) {
                const registrations = await navigator.serviceWorker.getRegistrations();
                for (let registration of registrations) {
                    await registration.unregister();
                }
            }
            const names = await caches.keys();
            for (let name of names) {
                await caches.delete(name);
            }
            localStorage.clear();
            window.location.reload(true);
        }
    };

    // Cleanup and Security: Logout on reload (F5)
    // Verificación de acceso y Migración perezosa
    // Cargar modelos, descriptor del empleado y configuraciones generales
    useEffect(() => {
        const loadModelsAndData = async () => {
            try {
                // 1. Cargar Configuración de Storage
                const snapSettings = await getDoc(doc(db, 'settings', 'employeeFields'));
                if (snapSettings.exists()) {
                    const d = snapSettings.data();
                    setStorageSettings({
                        storage_saveAsistencia: d.storage_saveAsistencia !== false,
                        storage_saveIncidentes: d.storage_saveIncidentes !== false,
                        security_liveness: d.security_liveness !== false
                    });
                    setButtonLabels({
                        entry: d.ui_labelEntry || "Registrar Entrada",
                        exit: d.ui_labelExit || "Registrar Salida",
                        incident: d.ui_labelIncident || "Reportar Novedad"
                    });
                    if (d.security_faceThreshold !== undefined) {
                        setFaceThreshold(d.security_faceThreshold);
                    }
                }

                // 1.5 Cargar Estado de la Licencia
                const licStatus = await fetchLicenseStatus();
                if (licStatus && licStatus.decoded && (!licStatus.decoded.isValid || licStatus.decoded.isExpired)) {
                    setIsLicenseValid(false);
                }

                // 2. Cargar Modelos Faciales
                const MODEL_URL = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/model/';
                await Promise.all([
                    faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),
                    faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL),
                    faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL)
                ]);
                setModelsLoaded(true);

                // 3. Cargar datos del empleado actual
                if (currentUser) {
                    const q = query(collection(db, "employees"), where("email", "==", currentUser.email));
                    const snap = await getDocs(q);
                    if (!snap.empty) {
                        const data = snap.docs[0].data();
                        if (data.faceDescriptor) {
                            setSavedDescriptor(new Float32Array(data.faceDescriptor));
                        }
                    }
                }
            } catch (err) {
                console.error("Error cargando modelos/datos:", err);
            }
        };
        loadModelsAndData();

        const checkAccess = async () => {
            if (!currentUser) return;

            try {
                const q = query(collection(db, "employees"), where("email", "==", currentUser.email));
                const querySnapshot = await getDocs(q);

                if (querySnapshot.empty) {
                    console.warn("Acceso denegado: Usuario no encontrado en lista activa.");
                    logout();
                    navigate('/login');
                }
            } catch (err) {
                console.error("Error verificando acceso:", err);
            }
        };

        checkAccess();

        // Verificar ESTADO DEL USUARIO (Entrada/Salida)
        // Sin orderBy para no requerir índice compuesto — ordenamos en el cliente
        const checkLastStatus = async () => {
            if (!currentUser) {
                setLoadingState(false);
                return;
            }
            try {
                // Solo WHERE sin orderBy = no necesita índice compuesto
                const q = query(
                    collection(db, "attendance"),
                    where("usuario", "==", currentUser.email)
                );
                const snap = await getDocs(q);

                if (snap.empty) {
                    setAllowedActions({ entry: true, exit: false });
                } else {
                    const docs = snap.docs.map(d => d.data());

                    // Ordenar del más reciente al más antiguo (manejo seguro si timestamp es null)
                    docs.sort((a, b) => {
                        const tA = (a.timestamp && a.timestamp.toMillis) ? a.timestamp.toMillis() : 0;
                        const tB = (b.timestamp && b.timestamp.toMillis) ? b.timestamp.toMillis() : 0;
                        return tB - tA;
                    });

                    const lastRecord = docs[0];
                    const lastType = lastRecord.tipo;
                    console.log(`✅ Último registro: tipo=${lastType}`);

                    if (lastType === 'Salida') {
                        setAllowedActions({ entry: true, exit: false });
                    } else if (lastType === 'Entrada') {
                        const lastTime = (lastRecord.timestamp && lastRecord.timestamp.toDate)
                            ? lastRecord.timestamp.toDate()
                            : new Date(0); // Si no hay timestamp, forzar reinicio

                        const diffHours = (new Date() - lastTime) / (1000 * 60 * 60);

                        if (diffHours > 20) {
                            console.log("⚠️ Ciclo reiniciado por tiempo (>20h)");
                            setAllowedActions({ entry: true, exit: false });
                        } else {
                            setAllowedActions({ entry: false, exit: true });
                        }
                    } else {
                        // Tipo desconocido o incidente -> permitir entrada
                        setAllowedActions({ entry: true, exit: false });
                    }
                }
            } catch (err) {
                console.error("❌ Error verificando estado:", err);
                setAllowedActions({ entry: true, exit: false }); // Fallback seguro
            } finally {
                setLoadingState(false); // SIEMPRE - pase lo que pase
            }
        };
        checkLastStatus();


        const handleUnload = () => {
            logout();
        };
        window.addEventListener('beforeunload', handleUnload);

        return () => {
            window.removeEventListener('beforeunload', handleUnload);
            if (streamRef.current) {
                streamRef.current.getTracks().forEach(track => track.stop());
            }
        };
    }, [logout, currentUser]);

    // --- LIVENESS: Eye Aspect Ratio helper ---
    const calcEAR = (eyePts) => {
        // eyePts: array of 6 {x, y} points (landmarks for one eye)
        const dist = (a, b) => Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
        const A = dist(eyePts[1], eyePts[5]);
        const B = dist(eyePts[2], eyePts[4]);
        const C = dist(eyePts[0], eyePts[3]);
        return (A + B) / (2.0 * C);
    };

    // --- LIVENESS: Reto de Rotación de Cabeza ---
    // Detecta el giro de la cabeza (Yaw) usando la posición de la nariz relativa a los ojos.
    // Requiere: 1. Mirar al frente -> 2. Girar a la izquierda -> 3. Volver al frente.
    const startLivenessCheck = () => {
        isLivenessRunningRef.current = true;
        setBlinkCount(0);
        blinkCountRef.current = 0;

        // Estados del reto: 0=Esperando frente, 1=Girando izquierda, 2=Volviendo al frente
        let challengeState = 0;
        let isDetecting = false;

        const loop = async () => {
            if (!isLivenessRunningRef.current) return;

            if (!isDetecting && videoRef.current && videoRef.current.readyState === 4) {
                isDetecting = true;
                try {
                    const detection = await faceapi
                        .detectSingleFace(
                            videoRef.current,
                            new faceapi.TinyFaceDetectorOptions({ inputSize: 224, scoreThreshold: 0.3 })
                        )
                        .withFaceLandmarks();

                    if (detection) {
                        const landmarks = detection.landmarks.positions;
                        const leftEye = landmarks[36];  // Extremo ojo izq
                        const rightEye = landmarks[45]; // Extremo ojo der
                        const nose = landmarks[30];     // Punta nariz

                        // Cálculo de Yaw simplificado (0.5 es centro, <0.3 es giro a izq, >0.7 es giro a der)
                        // Usamos escala de pantalla (ojo izq tiene X menor que ojo der usualmente)
                        const eyeDist = rightEye.x - leftEye.x;
                        const noseFromLeft = nose.x - leftEye.x;
                        const yawRatio = noseFromLeft / eyeDist;

                        if (challengeState === 0) {
                            // Paso 0: Mirar al frente
                            if (yawRatio > 0.4 && yawRatio < 0.6) {
                                challengeState = 1;
                                blinkCountRef.current = 20;
                                setBlinkCount(20);
                                setStatusMessage('¡Bien! Ahora gire la cabeza a la IZQUIERDA');
                            } else {
                                setStatusMessage('Póngase de frente a la cámara');
                            }
                        } else if (challengeState === 1) {
                            // Paso 1: Girar a la izquierda (yawRatio disminuye)
                            if (yawRatio < 0.35) {
                                challengeState = 2;
                                blinkCountRef.current = 60;
                                setBlinkCount(60);
                                setStatusMessage('Excelente. Ahora vuelva al CENTRO');
                            }
                            // Si se queda demasiado tiempo o gira al revés, no hacemos nada, solo esperamos
                        } else if (challengeState === 2) {
                            // Paso 2: Volver al frente
                            if (yawRatio > 0.45 && yawRatio < 0.65) {
                                challengeState = 3;
                                blinkCountRef.current = 100;
                                setBlinkCount(100);
                                setStatusMessage('¡Identidad confirmada!');
                                isLivenessRunningRef.current = false;
                                setAutoCapturePending(true);
                                return;
                            }
                        }
                    } else {
                        // Rostro perdido - Opcional: Reiniciar si tarda mucho
                        // setStatusMessage('Rostro no detectado');
                    }
                } catch (err) {
                    console.error("Liveness Error:", err);
                } finally {
                    isDetecting = false;
                }
            }

            if (isLivenessRunningRef.current) {
                livenessIntervalRef.current = requestAnimationFrame(loop);
            }
        };

        livenessIntervalRef.current = requestAnimationFrame(loop);
    };


    const startCamera = async (facingMode = 'user') => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode },
                audio: false
            });
            streamRef.current = stream;
            setCameraReady(true);
        } catch (err) {
            console.error("Error accessing camera:", err);
            alert("No se pudo acceder a la cámara. Verifique los permisos.");
            setStatusMessage('');

            setStep('idle');
            setMode(null);
        }
    };

    // Efecto para asignar el flujo de video cuando el elemento esté montado
    useEffect(() => {
        if (step === 'camera' && cameraReady && videoRef.current && streamRef.current) {
            console.log('[Dashboard] Asignando stream al video, mode:', modeRef.current);
            videoRef.current.srcObject = streamRef.current;
            videoRef.current.play().catch(e => console.error('Error reproduciendo video:', e));

            if (modeRef.current !== 'incident' && modelsLoaded) {
                // Esperar a que el video tenga frames reales (readyState === 4)
                const waitForVideo = setInterval(() => {
                    if (videoRef.current && videoRef.current.readyState === 4) {
                        clearInterval(waitForVideo);
                        if (storageSettings.security_liveness !== false) {
                            console.log('[Liveness] Video listo, iniciando detección de parpadeo...');
                            startLivenessCheck();
                        } else {
                            console.log('[Liveness] Video listo, Liveness desactivado -> Captura manual habilitada.');
                            setStatusMessage('Posicione su rostro y presione Tomar Foto Ahora');
                        }
                    }
                }, 100);
            } else if (modeRef.current === 'incident') {
                // Incidencias no requieren validación de vida
            }
        }
    }, [step, cameraReady, modelsLoaded]);

    const stopCamera = () => {
        // Detener el loop de liveness (requestAnimationFrame o intervalo)
        isLivenessRunningRef.current = false;
        if (livenessIntervalRef.current) {
            cancelAnimationFrame(livenessIntervalRef.current);
            livenessIntervalRef.current = null;
        }
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        setCameraReady(false);
    };

    const handleStopCamera = () => {
        stopCamera();
        setStep('idle');
        setMode(null);
        modeRef.current = null;
        setStatusMessage('');
        setBlinkCount(0);
        setAutoCapturePending(false);
        blinkCountRef.current = 0;
        eyeClosedRef.current = false;
    };

    const handleStart = async (selectedMode) => {
        setMode(selectedMode);
        modeRef.current = selectedMode; // Ref para evitar stale closures
        setStep('camera');
        setStatusMessage('');
        setIncidentDescription('');
        // Reset liveness for new session
        isLivenessRunningRef.current = false;
        setBlinkCount(0);
        setAutoCapturePending(false);
        blinkCountRef.current = 0;
        eyeClosedRef.current = false;

        // Cámara trasera para incidentes, frontal para asistencia
        const facingMode = selectedMode === 'incident' ? 'environment' : 'user';
        await startCamera(facingMode);

        if (!navigator.geolocation) {
            alert("Geolocalización no soportada en este navegador.");
            setStep('idle');
        }
    };

    const [capturedData, setCapturedData] = useState(null);

    const capture = useCallback(async () => {
        if (isCapturing) return;
        setIsCapturing(true);

        try {
            // 0. Manual Capture using Canvas
            if (!videoRef.current || !canvasRef.current) throw new Error("Cámara no lista");

            const video = videoRef.current;
            const canvas = canvasRef.current;

            // Set canvas dimensions to match video
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;

            // Draw
            const context = canvas.getContext('2d');
            context.drawImage(video, 0, 0, canvas.width, canvas.height);

            const imageSrc = canvas.toDataURL('image/jpeg', 0.8); // Higher quality for sharing
            if (!imageSrc) throw new Error("Error generando imagen");

            // --- NUEVO FLUJO: VERIFICACIÓN FACIAL INMEDIATA ---
            if (savedDescriptor) {
                setStep('processing');
                setStatusMessage('Verificando identidad facial...');
                setVerifyingFace(true);

                try {
                    // Detectar directamente desde el video (más rápido y preciso)
                    const detection = await faceapi.detectSingleFace(
                        video,
                        new faceapi.TinyFaceDetectorOptions()
                    ).withFaceLandmarks().withFaceDescriptor();

                    if (!detection) {
                        setFaceError('No se pudo detectar tu rostro. Asegúrate de tener buena luz y estar frente a la cámara.');
                        setFaceVerified(false);
                    } else {
                        const distance = faceapi.euclideanDistance(detection.descriptor, savedDescriptor);
                        console.log("Distancia facial:", distance);
                        // Umbral configurable (por defecto 0.63)
                        // Esto mejora la seguridad ante suplantaciones
                        if (distance < faceThreshold) {
                            setFaceVerified(true);
                            setFaceError('');
                        } else {
                            setFaceError('La identidad facial no coincide con el registro.');
                            setFaceVerified(false);
                        }
                    }
                } catch (faceErr) {
                    console.error("Error en detección facial:", faceErr);
                    setFaceError('Error en el sensor de reconocimiento. Reintenta.');
                    setFaceVerified(false);
                } finally {
                    setVerifyingFace(false);
                }
            } else {
                setFaceVerified(true); // Permitir si no hay registro previo
            }

            // AHORA DETENEMOS LA CÁMARA
            stopCamera();

            // CONTINUAMOS CON LOS DATOS LENTOS (GPS, HORA)
            setStatusMessage('Obteniendo ubicación y hora...');

            // 1. Get Location
            const position = await new Promise((resolve, reject) => {
                navigator.geolocation.getCurrentPosition(resolve, reject, {
                    enableHighAccuracy: true,
                    timeout: 8000, // Aumentado timeout para móviles lentos
                    maximumAge: 0
                });
            });

            const { latitude, longitude, accuracy } = position.coords;

            // 2. Get Time
            const serverTime = await fetchServerTime();

            setStatusMessage('Obteniendo dirección...');

            // 3. Get Address
            const address = await fetchLocationName(latitude, longitude);

            setStatusMessage('Procesando marca de agua...');

            // 4. Watermark
            const watermarkedImage = await addWatermarkToImage(imageSrc, {
                employeeId: currentUser.email,
                timestamp: serverTime,
                coords: `${latitude.toFixed(5)}, ${longitude.toFixed(5)}`,
                locationName: address,
                mode: mode
            });

            // STORE DATA FOR PREVIEW, DONT SAVE YET
            const now = new Date();
            const dateStr = now.toLocaleDateString('es-ES');
            const timeStr = now.toLocaleTimeString('es-ES');

            let tipoLabel = 'Entrada';
            if (mode === 'exit') tipoLabel = 'Salida';
            else if (mode === 'incident') tipoLabel = 'Novedad';

            setCapturedData({
                image: watermarkedImage,
                metadata: {
                    usuario: currentUser.email,
                    tipo: tipoLabel,
                    fecha: dateStr,
                    hora: timeStr,
                    localidad: address,
                    timestamp: serverTimestamp()
                }
            });

            setStep('preview');
            setIsCapturing(false);

        } catch (error) {
            console.error(error);
            alert(`Error: ${error.message}`);
            stopCamera();
            setStep('idle');
            setIsCapturing(false);
        }
    }, [mode, currentUser, isCapturing]);

    // Auto-captura al completar los 2 parpadeos
    useEffect(() => {
        if (autoCapturePending && !isCapturing) {
            setAutoCapturePending(false);
            capture();
        }
    }, [autoCapturePending, isCapturing, capture]);

    const shareImage = async () => {
        if (!capturedData || !capturedData.image) return;

        try {
            // Convert DataURL to Blob
            const response = await fetch(capturedData.image);
            const blob = await response.blob();

            // Nombre del archivo según el modo
            const fileName = mode === 'incident' ? 'incidente_evidencia.jpg' : 'asistencia_evidencia.jpg';
            const file = new File([blob], fileName, { type: "image/jpeg" });

            // Texto base
            let shareText;

            if (mode === 'incident') {
                const desc = incidentDescription.trim();
                shareText = `⚠️ INCIDENTE`;
                if (desc) {
                    shareText += `\n📝 ${desc}`;
                }
            } else {
                shareText = `Usuario: ${capturedData.metadata.usuario}\nFecha: ${capturedData.metadata.fecha} ${capturedData.metadata.hora}\nAcción: ${capturedData.metadata.tipo}`;
            }

            const shareData = {
                title: mode === 'incident' ? '⚠️ Reporte de Novedad' : 'Registro de Asistencia',
                text: shareText,
                files: [file]
            };

            // Intentar compartir directamente
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                // Fallback: descargar imagen
                const link = document.createElement('a');
                link.href = capturedData.image;
                link.download = `${mode === 'incident' ? 'incidente' : 'asistencia'}_${capturedData.metadata.fecha.replace(/\//g, '-')}_${capturedData.metadata.hora.replace(/:/g, '-')}.jpg`;
                link.click();
            }
        } catch (error) {
            console.error("Error sharing:", error);
            // Si el usuario cancela o hay error, no hacer nada
            // Los datos ya están guardados
        }
    };


    const saveRecord = async () => {
        if (!capturedData) return false;
        setStep('processing');
        setStatusMessage('Guardando registro...');

        try {
            if (mode === 'incident') {
                // Guardar en colección separada con descripción
                await addDoc(collection(db, "incidents"), {
                    ...capturedData.metadata,
                    descripcion: incidentDescription.trim() || '(Sin descripción)',
                });
            } else {
                await addDoc(collection(db, "attendance"), capturedData.metadata);
            }
            return true;
        } catch (error) {
            console.error(error);
            alert(`Error guardando datos: ${error.message}`);
            setStep('preview');
            return false;
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B] flex flex-col">
            {/* Header */}
            <div className="bg-white shadow p-4 flex justify-between items-center gap-2 overflow-x-auto">
                <h1 className="text-lg font-bold text-gray-800 flex-1 text-left truncate">Control Asistencia</h1>
                <button onClick={() => logout()} className="text-red-500 text-xs font-semibold hover:text-red-700 shrink-0">Salir</button>
            </div>

            {(showInstallBtn && !isStandalone) && (
                <div className="bg-green-500 p-2 flex justify-center animate-pulse">
                    <button
                        onClick={handleInstallClick}
                        className="text-white text-xs font-bold uppercase tracking-wider flex items-center gap-2"
                    >
                        + Descargar Aplicación en Celular
                    </button>
                </div>
            )}

            {(isIOS && !isStandalone && !showInstallBtn) && (
                <div className="bg-blue-600 p-2 flex justify-center items-center gap-2 text-[10px] text-white overflow-x-auto whitespace-nowrap">
                    <span>📱 iPhone: Toca "Compartir" y "Añadir a pantalla de inicio"</span>
                </div>
            )}

            <div className="flex-1 p-4 flex flex-col items-center justify-center max-w-md mx-auto w-full">

                {step === 'idle' && (
                    <div className="grid grid-cols-1 gap-6 w-full">
                        <div className="bg-white p-6 rounded-xl shadow-2xl text-center">
                            <h2 className="text-lg font-medium text-gray-600 mb-2">Bienvenido, {currentUser.email}</h2>
                            {loadingState ? (
                                <p className="text-sm text-blue-500 animate-pulse">Verificando estado de asistencia...</p>
                            ) : (
                                <p className="text-sm text-gray-400">
                                    {allowedActions.entry ? 'Es momento de registrar tu ENTRADA.' : 'Tienes una entrada pendiente. Registra tu SALIDA.'}
                                </p>
                            )}
                        </div>

                        {isLicenseValid ? (
                            <React.Fragment>
                                {!loadingState && allowedActions.entry && (
                                    <button
                                        onClick={() => handleStart('entry')}
                                        className="group relative flex flex-col items-center justify-center p-8 bg-gradient-to-tr from-green-400 to-green-600 rounded-2xl shadow-2xl hover:shadow-2xl transition transform hover:scale-105 active:scale-95 animate-fade-in"
                                    >
                                        <LogIn className="w-12 h-12 text-white mb-2" />
                                        <span className="text-2xl font-bold text-white">{buttonLabels.entry}</span>
                                    </button>
                                )}

                                {!loadingState && allowedActions.exit && (
                                    <button
                                        onClick={() => handleStart('exit')}
                                        className="group relative flex flex-col items-center justify-center p-8 bg-gradient-to-tr from-red-400 to-red-600 rounded-2xl shadow-2xl hover:shadow-2xl transition transform hover:scale-105 active:scale-95 animate-fade-in"
                                    >
                                        <LogOut className="w-12 h-12 text-white mb-2" />
                                        <span className="text-2xl font-bold text-white">{buttonLabels.exit}</span>
                                    </button>
                                )}

                                {/* Mensaje visual de bloqueo si uno está deshabilitado */}
                                {!loadingState && !allowedActions.entry && (
                                    <div className="opacity-40 grayscale flex flex-col items-center justify-center p-4 border-2 border-dashed border-gray-300 rounded-xl">
                                        <span className="text-gray-400 font-bold block mb-1">Entrada Bloqueada</span>
                                        <span className="text-[10px] text-gray-400 text-center">Debes marcar salida primero o esperar 20h</span>
                                    </div>
                                )}
                                {!loadingState && !allowedActions.exit && (
                                    <div className="opacity-40 grayscale flex flex-col items-center justify-center p-4 border-2 border-dashed border-gray-300 rounded-xl">
                                        <span className="text-gray-400 font-bold block mb-1">Salida Bloqueada</span>
                                        <span className="text-[10px] text-gray-400 text-center">Debes marcar entrada primero</span>
                                    </div>
                                )}
                                {/* Botón INCIDENTE — siempre visible, sin restricción de ciclo */}
                                {!loadingState && (
                                    <button
                                        onClick={() => handleStart('incident')}
                                        className="group relative flex flex-col items-center justify-center p-5 bg-gradient-to-tr from-orange-400 to-orange-600 rounded-2xl shadow-2xl hover:shadow-2xl transition transform hover:scale-105 active:scale-95 animate-fade-in"
                                    >
                                        <TriangleAlert className="w-8 h-8 text-white mb-1" />
                                        <span className="text-xl font-bold text-white">{buttonLabels.incident}</span>
                                        <span className="text-xs text-orange-100 mt-1">Registro de Novedades, Mantenimientos o Incidentes.</span>
                                    </button>
                                )}
                            </React.Fragment>
                        ) : (
                            <div className="col-span-2 bg-red-50 border-2 border-red-500 rounded-2xl p-6 text-center shadow-2xl animate-pulse">
                                <TriangleAlert className="w-12 h-12 text-red-500 mx-auto mb-3" />
                                <h3 className="text-xl font-bold text-red-700 mb-2">Servicio Suspendido</h3>
                                <p className="text-red-600 font-medium">
                                    La licencia del sistema ha expirado.<br />
                                    El registro de asistencia y novedades está temporalmente deshabilitado.
                                </p>
                                <p className="text-sm mt-4 text-red-500">
                                    Use el botón CONFIG para activar una nueva licencia.
                                </p>
                            </div>
                        )}
                    </div>
                )}

                {step === 'camera' && (
                    <div className="w-full flex flex-col items-center animate-fade-in">
                        <h2 className="text-xl font-bold mb-4 capitalize text-gray-800">
                            {mode === 'incident' ? `⚠️ ${buttonLabels.incident}` : `${buttonLabels[mode === 'entry' ? 'entry' : 'exit']}`}
                        </h2>

                        {/* Native Video Element */}
                        <div className="relative rounded-2xl overflow-hidden shadow-2xl border-4 bg-black w-full aspect-[3/4] max-w-[280px]"
                            style={{ borderColor: mode === 'incident' ? 'white' : blinkCount >= 1 ? '#22c55e' : '#3b82f6' }}>
                            <video
                                ref={videoRef}
                                autoPlay
                                playsInline
                                muted
                                className={`w-full h-full object-cover ${mode !== 'incident' ? 'transform scale-x-[-1]' : ''}`}
                            />
                            <canvas ref={canvasRef} className="hidden" />
                            <div className="absolute inset-0 border-2 border-white/30 rounded-2xl pointer-events-none"></div>

                            {/* Overlay info */}
                            <div className="absolute bottom-4 left-4 right-4 bg-black/50 backdrop-blur text-white p-2 rounded text-xs">
                                <div className="flex items-center gap-1"><MapPin size={12} /> Buscando GPS...</div>
                                {mode === 'incident'
                                    ? <div className="flex items-center gap-1"><TriangleAlert size={12} /> Fotografía el área afectada</div>
                                    : storageSettings.security_liveness === false
                                        ? <div className="flex items-center gap-1"><Camera size={12} /> Posicione su rostro</div>
                                        : <div className="flex items-center gap-1"><Camera size={12} /> Mueva la cabeza para registrar</div>
                                }
                            </div>

                            {/* Progreso movimiento — top right badge */}
                            {mode !== 'incident' && storageSettings.security_liveness !== false && (
                                <div className={`absolute top-3 right-3 text-white text-xs font-bold px-2 py-1 rounded-full shadow-lg ${blinkCount >= 100 ? 'bg-green-500' : 'bg-blue-500'}`}>
                                    {blinkCount}%
                                </div>
                            )}
                        </div>

                        {/* Barra de movimiento — solo si liveness está activo */}
                        {mode !== 'incident' && storageSettings.security_liveness !== false && (
                            <div className="mt-3 w-full max-w-[280px]">
                                <div className="bg-blue-50 border border-blue-200 rounded-xl p-3">
                                    <p className="text-xs font-bold text-blue-700 text-center mb-2">
                                        {statusMessage || '🙂 Mueva la cabeza ligeramente'}
                                    </p>
                                    <div className="w-full bg-blue-100 rounded-full h-3">
                                        <div
                                            className="h-3 rounded-full transition-all duration-150"
                                            style={{
                                                width: `${blinkCount}%`,
                                                background: blinkCount >= 100
                                                    ? 'linear-gradient(90deg, #22c55e, #16a34a)'
                                                    : 'linear-gradient(90deg, #3b82f6, #2563eb)'
                                            }}
                                        />
                                    </div>
                                    <p className="text-[10px] text-blue-400 text-center mt-1">
                                        {blinkCount < 20 ? 'Mire al frente...' : blinkCount < 60 ? '¡Bien! Gire a la IZQUIERDA...' : blinkCount < 100 ? '¡Casi listo! Vuelva al CENTRO 🟢' : '✅ Identidad Confirmada'}
                                    </p>
                                </div>
                            </div>
                        )}


                        <div className="mt-4 flex gap-4">
                            <button
                                onClick={handleStopCamera}
                                className="px-6 py-3 rounded-full bg-gray-200 text-gray-700 font-bold hover:bg-gray-300"
                            >
                                Cancelar
                            </button>
                            {/* Mostrar "Capturar" para incidentes o si la seguridad de movimiento está desactivada */}
                            {(mode === 'incident' || (mode !== 'incident' && storageSettings.security_liveness === false)) && (
                                <button
                                    onClick={capture}
                                    disabled={step === 'processing'}
                                    className={`px-8 py-3 rounded-full text-white font-bold shadow-2xl transition transform active:translate-y-1 ${step === 'processing'
                                            ? 'bg-gray-400 cursor-not-allowed'
                                            : mode === 'incident'
                                                ? 'bg-blue-600 hover:bg-blue-700'
                                                : 'bg-[#2863eb] hover:bg-[#1d4ed8]' /* Un azul más similar a la imagen */
                                        } ${mode !== 'incident' ? 'flex items-center gap-2 w-full max-w-[280px] justify-center' : ''}`}
                                >
                                    {mode !== 'incident' && <Camera size={20} />}
                                    {step === 'processing' ? 'Procesando...' : mode === 'incident' ? 'Capturar' : 'Tomar Foto Ahora'}
                                </button>
                            )}
                        </div>
                        {/* Mensaje inferior si liveness está desactivado (similar a la imagen del usuario) */}
                        {mode !== 'incident' && storageSettings.security_liveness === false && (
                            <p className="text-xs text-gray-500 mt-3 max-w-[280px] text-center opacity-80">
                                Asegúrese de que su rostro sea visible antes de capturar.
                            </p>
                        )}
                    </div>
                )}


                {step === 'processing' && (
                    <div className="text-center p-10">
                        <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-500 mx-auto mb-4"></div>
                        <p className="text-gray-600 font-medium">{statusMessage}</p>
                    </div>
                )}

                {step === 'preview' && capturedData && (
                    <div className="w-full flex flex-col items-center animate-fade-in">
                        <h2 className="text-xl font-bold mb-2 text-gray-800">
                            {mode === 'incident' ? '⚠️ Vista Previa de la Novedad' : 'Vista Previa'}
                        </h2>
                        <p className="text-sm text-gray-500 mb-4 text-center">
                            {mode === 'incident'
                                ? 'Describe la novedad antes de guardar.'
                                : faceVerified
                                    ? 'Identidad verificada correctamente. Comparte esta imagen como evidencia.'
                                    : 'No se pudo verificar tu identidad facial.'}
                        </p>

                        {!faceVerified && faceError && mode !== 'incident' && (
                            <div className="bg-red-100 text-red-700 p-3 rounded-lg flex items-center gap-2 mb-4 w-full max-w-sm">
                                <ShieldAlert size={20} />
                                <span className="text-xs font-bold">{faceError}</span>
                            </div>
                        )}

                        <div className="relative rounded-2xl overflow-hidden shadow-2xl border-4 bg-gray-900 w-full max-w-sm mb-4"
                            style={{ borderColor: mode === 'incident' ? '#ea580c' : faceVerified ? '#22c55e' : '#ef4444' }}>
                            <img src={capturedData.image} alt="Capture" className="w-full h-auto" />

                            {!faceVerified && mode !== 'incident' && (
                                <button
                                    onClick={handleStopCamera}
                                    className="absolute top-4 left-4 flex items-center gap-2 px-4 py-2 bg-red-600 text-white font-bold rounded-lg shadow-2xl hover:bg-red-700 transition transform hover:scale-105"
                                >
                                    <Camera size={20} />
                                    REPETIR FOTO
                                </button>
                            )}

                            {(faceVerified || mode === 'incident') && (
                                <div className={`absolute top-4 right-4 p-1 rounded-full shadow-2xl ${mode === 'incident' ? 'bg-orange-500' : 'bg-green-500'} text-white`}>
                                    {mode === 'incident' ? <TriangleAlert size={24} /> : <UserCheck size={24} />}
                                </div>
                            )}
                        </div>

                        {/* Campo de descripción SOLO para novedades */}
                        {mode === 'incident' && (
                            <div className="w-full max-w-sm mb-4">
                                <label className="block text-sm font-bold text-orange-700 mb-1">📝 Descripción de la novedad *</label>
                                <textarea
                                    value={incidentDescription}
                                    onChange={(e) => setIncidentDescription(e.target.value)}
                                    placeholder="Describe detalladamente lo que ocurrió, el área afectada y el tipo de daño..."
                                    rows={4}
                                    className="w-full border-2 border-orange-300 rounded-xl p-3 text-sm focus:outline-none focus:border-orange-500 resize-none"
                                />
                            </div>
                        )}

                        <div className="flex flex-col gap-3 w-full max-w-xs">
                            <button
                                onClick={async () => {
                                    if (mode !== 'incident' && !faceVerified) {
                                        alert("Verificación facial fallida. No se puede guardar el registro.");
                                        return;
                                    }
                                    if (mode === 'incident' && !incidentDescription.trim()) {
                                        alert("Por favor describe la novedad antes de guardar.");
                                        return;
                                    }

                                    const saved = await saveRecord();
                                    if (!saved) return;

                                    // ¿Debemos guardar la foto en Storage?
                                    const isIncidente = mode === 'incident';
                                    const savePhoto = isIncidente ? storageSettings.storage_saveIncidentes : storageSettings.storage_saveAsistencia;

                                    if (savePhoto) {
                                        // Subir foto a Storage en segundo plano (sin await)
                                        // para no bloquear el selector de WhatsApp (navigator.share requiere gesto directo)
                                        uploadPhoto(
                                            capturedData.image,
                                            isIncidente ? 'incidente' : capturedData.metadata.tipo,
                                            capturedData.metadata.usuario,
                                            capturedData.metadata.fecha,
                                            capturedData.metadata.hora,
                                        ).catch(err => console.error('Storage upload failed:', err));
                                    } else {
                                        console.log('Almacenamiento de foto desactivado por configuración.');
                                    }

                                    await shareImage();

                                    setStep('success');
                                    setStatusMessage('¡Registro Exitoso!');
                                    setTimeout(() => {
                                        logout();
                                    }, 3000);
                                }}
                                className={`w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl text-white font-bold shadow-2xl transition ${mode === 'incident'
                                    ? 'bg-orange-500 hover:bg-orange-600'
                                    : 'bg-green-600 hover:bg-green-700'
                                    }`}
                            >
                                <CheckCircle size={20} />
                                {mode === 'incident' ? 'Guardar Novedad y Compartir' : 'Guardar y Compartir'}
                            </button>
                            <button
                                onClick={() => { stopCamera(); setStep('idle'); setMode(null); }}
                                className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-gray-100 text-gray-600 font-bold hover:bg-gray-200 transition"
                            >
                                Cancelar
                            </button>
                        </div>
                    </div>
                )}

                {step === 'success' && (
                    <div className="text-center p-10 bg-white rounded-2xl shadow-2xl animate-fade-in">
                        <CheckCircle className="w-20 h-20 text-green-500 mx-auto mb-4" />
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">¡Registrado!</h2>
                        <p className="text-gray-600">Registro guardado exitosamente.</p>
                    </div>
                )}
            </div>
            {/* Version Indicator */}
            <div className="p-2 text-center flex flex-col items-center gap-1 opacity-50">
                <span className="text-[10px] text-black font-mono px-2 py-0.5 rounded">v{import.meta.env.VITE_APP_VERSION || '1.3.1'}</span>
                <button
                    onClick={clearAppCache}
                    className="text-[9px] text-blue-600 underline decoration-blue-300 hover:text-blue-800 transition pointer-events-auto"
                >
                    Limpiar App si no se actualiza
                </button>
            </div>
        </div>
    );
}

﻿// src/pages/Datos.jsx
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Trash2, ChevronLeft, ChevronRight, Loader2, FileText, CheckCircle } from 'lucide-react';
import { db } from '../firebaseConfig';
import { collection, query, where, addDoc, serverTimestamp, getDocs } from 'firebase/firestore';
import { useAuth } from '../contexts/AuthContext';

// ✅ Importamos desde los servicios
import {
    getAllAttendanceLogs,
    paginateLogs,
    deleteAttendanceLog,
    subscribeToAttendanceLogs
} from '../services/attendanceService';

import { getEmployeesMap } from '../services/employeeService';

const PAGE_SIZE = 100;

export default function Datos() {
    const [logs, setLogs] = useState([]);
    const [allLogs, setAllLogs] = useState([]);
    const [loading, setLoading] = useState(true);
    const [pageNumber, setPageNumber] = useState(1);
    const [hasMore, setHasMore] = useState(true);
    const [employeesMap, setEmployeesMap] = useState({});

    // Estado para Entrada Manual
    const [mUser, setMUser] = useState('');
    const [mType, setMType] = useState('Entrada');
    const [mDate, setMDate] = useState('');
    const [mHour, setMHour] = useState('12');
    const [mMinute, setMMinute] = useState('00');
    const [mAmPm, setMAmPm] = useState('AM');
    const [mSaving, setMSaving] = useState(false);

    const navigate = useNavigate();
    const { adminAccess } = useAuth();

    useEffect(() => {
        // Validación de seguridad específica para esta página
        if (!adminAccess['/datos']) {
            navigate('/login');
            return;
        }

        // Cargar mapa de empleados una vez
        const loadInitialData = async () => {
            const map = await getEmployeesMap();
            setEmployeesMap(map);
        };
        loadInitialData();

        // Suscripción en tiempo real
        setLoading(true);
        const unsubscribe = subscribeToAttendanceLogs((updatedLogs) => {
            setAllLogs(updatedLogs);
            setLoading(false);
        });

        // Limpieza al desmontar
        return () => unsubscribe();
    }, [adminAccess]);

    const loadLogs = async () => {
        // Esta función ahora solo es necesaria para manual entry si queremos forzar algo,
        // pero la suscripción ya se encarga de actualizar allLogs.
        // La dejamos vacía o la removemos si no se usa más que en el handleSubmit.
    };

    // Recalcular página cuando cambia pageNumber
    useEffect(() => {
        if (allLogs.length === 0) return;
        const { data, hasMore: more } = paginateLogs(allLogs, pageNumber, PAGE_SIZE);
        setLogs(data);
        setHasMore(more);
    }, [pageNumber, allLogs]);

    const handleManualEntry = async (e) => {
        e.preventDefault();
        if (!mUser || !mType || !mDate || !mHour || !mMinute || !mAmPm) {
            alert('Por favor completa todos los campos.');
            return;
        }

        const [y, m, d] = mDate.split('-');
        const dateStr = `${parseInt(d)}/${parseInt(m)}/${y}`;

        // Convertir a formato 24 horas para la base de datos
        let hour24 = parseInt(mHour, 10);
        if (mAmPm === 'PM' && hour24 !== 12) {
            hour24 += 12;
        } else if (mAmPm === 'AM' && hour24 === 12) {
            hour24 = 0;
        }
        const timeStr = `${hour24.toString().padStart(2, '0')}:${mMinute}:00`;

        try {
            setMSaving(true);
            const q = query(
                collection(db, "attendance"),
                where("usuario", "==", mUser.toLowerCase().trim()),
                where("fecha", "==", dateStr),
                where("tipo", "==", mType)
            );
            const snap = await getDocs(q);

            if (!snap.empty) {
                if (!window.confirm('Ya existe un registro con estos datos. ¿Desea sobreescribirlo?')) {
                    setMSaving(false);
                    return;
                }
                for (const docSnap of snap.docs) {
                    await deleteAttendanceLog(docSnap.id);
                }
            }

            await addDoc(collection(db, "attendance"), {
                usuario: mUser.toLowerCase().trim(),
                tipo: mType,
                fecha: dateStr,
                hora: timeStr,
                localidad: "ENTRADA MANUAL DE DATOS",
                timestamp: serverTimestamp()
            });

            alert('✅ Registro adicionado correctamente.');
            setMUser(''); setMDate(''); setMHour('12'); setMMinute('00'); setMAmPm('AM');
            // No hace falta llamar a loadLogs() porque onSnapshot detectará el nuevo doc
        } catch (error) {
            console.error(error);
            alert('Error al guardar el registro manual.');
        } finally {
            setMSaving(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm('¿Eliminar este registro permanentemente?')) return;
        try {
            await deleteAttendanceLog(id);
            setLogs(logs.filter(log => log.id !== id));
            setAllLogs(allLogs.filter(log => log.id !== id));
        } catch (error) {
            console.error(error);
            alert('No se pudo borrar el registro.');
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B] p-6">
            <div className="max-w-6xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2">
                        <FileText size={30} className="text-blue-600" />
                        Visor de Asistencia
                        <div className="flex items-center gap-1.5 px-2 py-0.5 bg-red-50 text-red-600 rounded-full border border-red-100 animate-pulse ml-2">
                            <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                            <span className="text-[10px] font-bold uppercase tracking-wider">Live</span>
                        </div>
                        <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-mono ml-1 border border-gray-200">v{import.meta.env.VITE_APP_VERSION}</span>
                    </h1>
                    <button onClick={() => navigate('/dashboard')} className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 transition">Volver</button>
                </div>


                {/* Tabla */}
                <div className="bg-white rounded-xl shadow-2xl overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-100 border-b">
                                <tr>
                                    <th className="p-4 font-semibold text-gray-600">Empleado</th>
                                    <th className="p-4 font-semibold text-gray-600">Usuario</th>
                                    <th className="p-4 font-semibold text-gray-600">Tipo</th>
                                    <th className="p-4 font-semibold text-gray-600">Fecha</th>
                                    <th className="p-4 font-semibold text-gray-600">Hora</th>
                                    <th className="p-4 font-semibold text-gray-600">Localidad</th>
                                    <th className="p-4 text-center">Borrar</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {loading ? (
                                    <tr><td colSpan="7" className="p-8 text-center text-gray-400">Cargando registros...</td></tr>
                                ) : logs.map((log) => {
                                    const emp = employeesMap[log.usuario] || { firstName: '-', lastName: '' };
                                    return (
                                        <tr key={log.id} className="hover:bg-gray-50 transition text-sm">
                                            <td className="p-4 font-bold">{emp.firstName} {emp.lastName}</td>
                                            <td className="p-4 text-gray-500">{log.usuario}</td>
                                            <td className="p-4">
                                                <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${log.tipo === 'Entrada' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                    {log.tipo}
                                                </span>
                                            </td>
                                            <td className="p-4">{log.fecha}</td>
                                            <td className="p-4">{log.hora}</td>
                                            <td className="p-4 text-xs text-gray-400 max-w-[200px] truncate" title={log.localidad}>{log.localidad}</td>
                                            <td className="p-4 text-center">
                                                <button onClick={() => handleDelete(log.id)} className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded transition">
                                                    <Trash2 size={16} />
                                                </button>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>

                    <div className="p-4 bg-gray-50 flex justify-between items-center border-t">
                        <p className="text-xs text-gray-500">Página {pageNumber}</p>
                        <div className="flex gap-2">
                            <button onClick={() => setPageNumber(1)} disabled={pageNumber === 1} className="px-3 py-1 bg-white border rounded text-xs">Inicio</button>
                            <button onClick={() => setPageNumber(p => Math.max(1, p - 1))} disabled={pageNumber === 1} className="flex items-center gap-1 px-3 py-1 bg-white border rounded text-xs"><ChevronLeft size={14} /> Ant.</button>
                            <button onClick={() => setPageNumber(p => p + 1)} disabled={!hasMore} className="flex items-center gap-1 px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Sig. <ChevronRight size={14} /></button>
                        </div>
                    </div>
                </div>

                {/* Entrada Manual al Final */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mt-8 mb-64 border-l-4 border-blue-500">
                    <h3 className="text-blue-700 font-bold flex items-center gap-2 mb-4">
                        <FileText size={20} />
                        Entrada Manual de Datos
                    </h3>
                    <form onSubmit={handleManualEntry} className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
                        <div>
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Usuario (Email)</label>
                            <input type="text" placeholder="ej: faus@bot.com" value={mUser} onChange={e => setMUser(e.target.value)} className="w-full px-3 py-2 border rounded-lg text-sm" required />
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Evento</label>
                            <select value={mType} onChange={e => setMType(e.target.value)} className="w-full px-3 py-2 border rounded-lg text-sm bg-white">
                                <option value="Entrada">Entrada</option>
                                <option value="Salida">Salida</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Fecha</label>
                            <input type="date" value={mDate} onChange={e => setMDate(e.target.value)} className="w-full px-3 py-2 border rounded-lg text-sm" required />
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Hora</label>
                            <div className="flex gap-1">
                                <select value={mHour} onChange={e => setMHour(e.target.value)} className="flex-1 py-2 border rounded-lg text-sm bg-white text-center px-0" required>
                                    {[...Array(12)].map((_, i) => {
                                        const h = (i + 1).toString().padStart(2, '0');
                                        return <option key={h} value={h}>{h}</option>;
                                    })}
                                </select>
                                <span className="flex items-center text-gray-500 font-bold">:</span>
                                <select value={mMinute} onChange={e => setMMinute(e.target.value)} className="flex-1 py-2 border rounded-lg text-sm bg-white text-center px-0" required>
                                    {[...Array(60)].map((_, i) => {
                                        const m = i.toString().padStart(2, '0');
                                        return <option key={m} value={m}>{m}</option>;
                                    })}
                                </select>
                                <select value={mAmPm} onChange={e => setMAmPm(e.target.value)} className="flex-1 py-2 border rounded-lg text-[11px] bg-white text-center font-bold px-0" required>
                                    <option value="AM">AM</option>
                                    <option value="PM">PM</option>
                                </select>
                            </div>
                        </div>
                        <button type="submit" disabled={mSaving} className="w-full h-[42px] bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 flex items-center justify-center gap-2">
                            {mSaving ? <Loader2 size={16} className="animate-spin" /> : <CheckCircle size={16} />} Adicionar
                        </button>
                    </form>
                </div>
            </div>
        </div >
    );
}

// src/pages/Informes.jsx
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Download, Calendar, Trash2, AlertTriangle, TriangleAlert, Image, Loader2, UserMinus, FileText } from 'lucide-react';
import DeleteEmployeeModal from '../components/DeleteEmployeeModal';
import { listPhotosByFilter, downloadPhotosAsZip, cleanOldPhotos } from '../services/storageService';
import { httpsCallable } from 'firebase/functions';
import { functions, db } from '../firebaseConfig';
import { exportToExcelHTML } from '../utils/exportUtils';
import { calculateLaborHours, parseStringDate } from '../utils/timeCalculator';
import { useAuth } from '../contexts/AuthContext';
import { collection, getDocs, query, orderBy, getDoc, doc } from 'firebase/firestore';

// ✅ Importamos desde los servicios
import {
    bulkDeleteByDateRange,
    bulkDeleteIncidentsByDateRange,
    filterLogsByDateRange,
    parseSpanishDate,
    getAllAttendanceLogs
} from '../services/attendanceService';

import { getEmployeesMap } from '../services/employeeService';

const FIELD_DEFS = [
    { key: 'documentoIdentidad', label: 'Documento de identidad', type: 'text', group: 'Identificación' },
    { key: 'fechaNacimiento', label: 'Fecha de nacimiento', type: 'date', group: 'Identificación' },
    { key: 'fechaIngreso', label: 'Fecha de ingreso', type: 'date', group: 'Identificación' },
    { key: 'infoBancaria', label: 'Información bancaria', type: 'text', group: 'Identificación' },
    { key: 'licenciaConducir', label: 'Licencia de conducir', type: 'text', group: 'Identificación' },
    { key: 'tallaUniforme', label: 'Talla de uniformes', type: 'text', group: 'Identificación' },
    { key: 'tallaCalzado', label: 'Talla de calzado', type: 'text', group: 'Identificación' },
    { key: 'alergias', label: 'Alergias / cond. médicas', type: 'text', group: 'Identificación' },
    { key: 'estadoCivil', label: 'Estado civil', type: 'text', group: 'Identificación' },
    { key: 'hijos', label: 'Hijos y edades', type: 'text', group: 'Identificación' },
    { key: 'grupoSanguineo', label: 'Grupo sanguíneo', type: 'text', group: 'Identificación' },
    { key: 'eps', label: 'EPS', type: 'text', group: 'Identificación' },
    { key: 'arl', label: 'ARL', type: 'text', group: 'Identificación' },
    { key: 'direccion', label: 'Dirección de residencia', type: 'text', group: 'Contacto' },
    { key: 'telefono', label: 'Teléfono personal', type: 'tel', group: 'Contacto' },
    { key: 'correoPersonal', label: 'Correo electrónico personal', type: 'email', group: 'Contacto' },
    { key: 'contactoEmergenciaNombre', label: 'Contacto emergencia (Nombre)', type: 'text', group: 'Contacto' },
    { key: 'contactoEmergenciaTelefono', label: 'Contacto emergencia (Tel.)', type: 'text', group: 'Contacto' },
    { key: 'cargo', label: 'Cargo o posición', type: 'text', group: 'Laboral' },
    { key: 'departamento', label: 'Departamento / Área', type: 'text', group: 'Laboral' },
    { key: 'tipoContrato', label: 'Tipo de contrato', type: 'text', group: 'Laboral' },
    { key: 'salario', label: 'Salario / Remuneración', type: 'text', group: 'Laboral' },
    { key: 'horario', label: 'Horario de trabajo', type: 'text', group: 'Laboral' },
    { key: 'nivelEstudios', label: 'Nivel educativo', type: 'text', group: 'Otros' },
    { key: 'certificaciones', label: 'Certificaciones relevantes', type: 'text', group: 'Otros' },
    { key: 'tallaCamisa', label: 'Talla de camisa/polo', type: 'text', group: 'Otros' },
    { key: 'tallaPantalon', label: 'Talla de pantalón', type: 'text', group: 'Otros' }
];

export default function Informes() {
    const [allLogs, setAllLogs] = useState([]);
    const [loading, setLoading] = useState(true);
    const [exporting, setExporting] = useState(false);
    const [deleting, setDeleting] = useState(false);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    // Incidentes export
    const [exportingIncidents, setExportingIncidents] = useState(false);
    const [incidentStartDate, setIncidentStartDate] = useState('');
    const [incidentEndDate, setIncidentEndDate] = useState('');
    const [incidentCsvUserFilter, setIncidentCsvUserFilter] = useState('');
    const [deletingIncidents, setDeletingIncidents] = useState(false);

    // CSV Asistencia export
    const [csvUserFilter, setCsvUserFilter] = useState('');
    const [exportFormatAttendance, setExportFormatAttendance] = useState('csv');
    const [attendanceReportType, setAttendanceReportType] = useState('estandar');
    const [timeConfig, setTimeConfig] = useState({});

    // Módulo Gestión Empleados
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [filterEmail, setFilterEmail] = useState('');
    const [exportingEmployees, setExportingEmployees] = useState(false);
    const [exportFormatEmployees, setExportFormatEmployees] = useState('csv');
    const [exportFormatIncidents, setExportFormatIncidents] = useState('csv');

    // Descargador de fotos
    const [photoTipo, setPhotoTipo] = useState('ambos');
    const [photoDesde, setPhotoDesde] = useState('');
    const [photoHasta, setPhotoHasta] = useState('');
    const [photoFiltroUser, setPhotoFiltroUser] = useState('');
    const [photoSearching, setPhotoSearching] = useState(false);
    const [photoProgress, setPhotoProgress] = useState({ current: 0, total: 0 });
    const [photoMsg, setPhotoMsg] = useState('');
    const [cleaningStorage, setCleaningStorage] = useState(false);
    const [storageConfig, setStorageConfig] = useState(null);

    const navigate = useNavigate();
    const { adminAccess, currentUser } = useAuth();

    useEffect(() => {
        if (!adminAccess['/informes']) {
            navigate('/login');
            return;
        }
        loadInitialData();
    }, [adminAccess]);

    const loadInitialData = async () => {
        setLoading(true);
        try {
            // Cargar logs para exportación
            const logs = await getAllAttendanceLogs();
            setAllLogs(logs);

            // Cargar config
            const snap = await getDoc(doc(db, 'settings', 'employeeFields'));
            if (snap.exists()) {
                const d = snap.data();
                setStorageConfig({
                    retentionAsistencia: d.storage_retentionAsistencia ?? 3,
                    retentionIncidentes: d.storage_retentionIncidentes ?? 18,
                    saveAsistencia: d.storage_saveAsistencia !== false,
                    saveIncidentes: d.storage_saveIncidentes !== false
                });
                setTimeConfig(d);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const handleManualCleanup = async () => {
        if (!storageConfig) return;
        if (!window.confirm(`¿Ejecutar limpieza manual de fotos más antiguas de ${storageConfig.retentionAsistencia} meses (asistencia) y ${storageConfig.retentionIncidentes} meses (incidentes)?`)) return;

        setCleaningStorage(true);
        try {
            const deleted = await cleanOldPhotos({
                asistencia: storageConfig.retentionAsistencia,
                incidentes: storageConfig.retentionIncidentes
            });
            alert(`✅ Limpieza completada. Se liberó espacio de ${deleted} fotos.`);
        } catch (err) {
            alert('❌ Error en la limpieza: ' + err.message);
        } finally {
            setCleaningStorage(false);
        }
    };

    const handleBulkDelete = async () => {
        if (!startDate || !endDate) {
            alert('Selecciona un rango de fechas para limpiar datos.');
            return;
        }
        if (!window.confirm(`⚠️ Se borrarán TODOS los registros entre ${startDate} y ${endDate}. ¿Continuar?`)) return;

        setDeleting(true);
        try {
            const count = await bulkDeleteByDateRange(startDate, endDate);
            alert(`Se han borrado ${count} registros con éxito.`);
            loadInitialData();
        } catch (error) {
            console.error(error);
            alert('Error al realizar la limpieza.');
        } finally {
            setDeleting(false);
        }
    };

    const handleBulkDeleteIncidents = async () => {
        if (!incidentStartDate || !incidentEndDate) {
            alert('Debes seleccionar fecha de inicio y fin para borrar en lote.');
            return;
        }
        const confirm1 = window.confirm(`⚠️ PELIGRO: Vas a borrar PERMANENTEMENTE las NOVEDADES desde ${incidentStartDate} hasta ${incidentEndDate}.\n\nEsta acción NO se puede deshacer.\n¿Deseas continuar?`);
        if (!confirm1) return;

        setDeletingIncidents(true);
        try {
            const deletedCount = await bulkDeleteIncidentsByDateRange(incidentStartDate, incidentEndDate);
            alert(`✅ Se borraron ${deletedCount} registros de novedades exitosamente.`);
        } catch (error) {
            console.error(error);
            alert('Hubo un error al borrar los registros.');
        } finally {
            setDeletingIncidents(false);
        }
    };

    const exportEmployeesToCSV = async () => {
        setExportingEmployees(true);
        try {
            const getUsersListFn = httpsCallable(functions, 'getUsersList');
            const result = await getUsersListFn();
            let authUsers = result.data.users;
            if (!authUsers || authUsers.length === 0) { alert('No hay empleados para exportar.'); return; }

            if (filterEmail.trim()) {
                const needle = filterEmail.trim().toLowerCase();
                authUsers = authUsers.filter(emp => (emp.email || '').toLowerCase().includes(needle));
                if (authUsers.length === 0) { alert(`No se encontró ningún empleado con el correo "${filterEmail.trim()}".`); return; }
            }

            const fsSnap = await getDocs(collection(db, 'employees'));
            const fsMap = {};
            fsSnap.forEach(d => {
                const data = d.data();
                if (data.email) fsMap[data.email.toLowerCase()] = data;
            });

            const activeOptionalKeys = FIELD_DEFS
                .filter(({ key }) => authUsers.some(u => {
                    const fs = fsMap[(u.email || '').toLowerCase()];
                    return fs && fs[key] !== undefined && fs[key] !== '';
                }))
                .map(({ key, label }) => ({ key, label }));

            const headers = ['Email/ID', 'Nombres', 'Apellidos', 'Fecha de Creacion', 'Ultimo Acceso', 'UID', ...activeOptionalKeys.map(f => f.label)];
            const rows = authUsers.map(emp => {
                const fs = fsMap[(emp.email || '').toLowerCase()] || {};
                return [
                    emp.email || '', fs.firstName || '', fs.lastName || '',
                    emp.creationTime ? new Date(emp.creationTime).toLocaleString('es-ES') : 'N/A',
                    emp.lastSignInTime ? new Date(emp.lastSignInTime).toLocaleString('es-ES') : 'N/A',
                    emp.uid || '',
                    ...activeOptionalKeys.map(({ key }) => fs[key] || '')
                ];
            });

            const ts = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
            if (exportFormatEmployees === 'xlsx') {
                exportToExcelHTML(`empleados_${ts}.xlsx`, headers, rows);
            } else {
                const escape = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
                const csvContent = '\ufeff' + [headers.join(','), ...rows.map(r => r.map(escape).join(','))].join('\n');
                const link = document.createElement('a');
                link.href = URL.createObjectURL(new Blob([csvContent], { type: 'text/csv;charset=utf-8;' }));
                link.download = `empleados_${ts}.csv`;
                link.click();
            }
        } catch (err) {
            console.error(err);
            alert('Error al exportar empleados.');
        } finally {
            setExportingEmployees(false);
        }
    };

    const exportToCSV = async () => {
        setExporting(true);
        try {
            let filtered = (startDate || endDate) ? filterLogsByDateRange(allLogs, startDate, endDate) : allLogs;
            if (csvUserFilter.trim()) {
                const searchStr = csvUserFilter.trim().toLowerCase();
                filtered = filtered.filter(log => (log.usuario || '').toLowerCase().includes(searchStr));
            }
            if (filtered.length === 0) { alert('No hay registros.'); return; }

            const employeesMap = await getEmployeesMap();
            const dayFormatter = new Intl.DateTimeFormat('es-ES', { weekday: 'long' });

            const sorted = [...filtered].sort((a, b) => {
                const dateA = parseStringDate(a.fecha, a.hora) || (a.timestamp ? a.timestamp.toDate() : new Date(0));
                const dateB = parseStringDate(b.fecha, b.hora) || (b.timestamp ? b.timestamp.toDate() : new Date(0));
                return dateA - dateB;
            });

            const byUser = {};
            sorted.forEach(log => {
                const key = (log.usuario || '').toLowerCase().trim();
                if (!byUser[key]) byUser[key] = [];
                byUser[key].push(log);
            });

            const shifts = [];
            Object.entries(byUser).forEach(([email, records]) => {
                let pendingEntry = null;
                records.forEach(rec => {
                    if (rec.tipo === 'Entrada') {
                        if (pendingEntry) shifts.push({ entry: pendingEntry, exit: null, email });
                        pendingEntry = rec;
                    } else if (rec.tipo === 'Salida') {
                        if (pendingEntry) { shifts.push({ entry: pendingEntry, exit: rec, email }); pendingEntry = null; }
                        else shifts.push({ entry: null, exit: rec, email });
                    }
                });
                if (pendingEntry) shifts.push({ entry: pendingEntry, exit: null, email });
            });

            let headers = [];
            let rows = [];

            if (attendanceReportType === 'estandar') {
                headers = ['Usuario', 'Nombres', 'Apellidos', 'Dia Entrada', 'Fecha Entrada', 'Hora Entrada', 'Localidad Entrada', 'Fecha Salida', 'Hora Salida', 'Localidad Salida', 'Almuerzo', 'Horas'];
                rows = shifts.map(({ entry, exit, email }) => {
                    const emp = employeesMap[email] || { firstName: '', lastName: '' };
                    let dia = '-';
                    if (entry?.fecha) {
                        const d = parseSpanishDate(entry.fecha);
                        dia = d ? dayFormatter.format(d) : '-';
                    }
                    let horasStr = '0';
                    let lunch = 'No';
                    if (entry && exit) {
                        const start = parseStringDate(entry.fecha, entry.hora);
                        const end = parseStringDate(exit.fecha, exit.hora);
                        const calc = calculateLaborHours(start, end, timeConfig);
                        if (!calc.error) {
                            horasStr = (calc.raw.totalMins / 60).toFixed(2);
                            if (calc.appliedLunchDeduction) lunch = `Sí (${(timeConfig.calc_lunchMins || 60) / 60} Hora${(timeConfig.calc_lunchMins || 60) / 60 > 1 ? 's' : ''})`;
                        }
                    }
                    return [
                        email, emp.firstName, emp.lastName, dia,
                        entry?.fecha || '-', entry?.hora || '-', entry?.localidad || '-',
                        exit?.fecha || '-', exit?.hora || '-', exit?.localidad || '-',
                        lunch, horasStr
                    ];
                });
            } else if (attendanceReportType === 'detallado_horas') {
                headers = ['Usuario', 'Nombres', 'Apellidos', 'Dia', 'F. Ingreso', 'H. Ingreso', 'F. Salida', 'H. Salida', 'Almuerzo Aplicado', 'Diurnas', 'Nocturnas', 'Dom Diu', 'Dom Noc', 'Total'];
                rows = shifts.map(({ entry, exit, email }) => {
                    const emp = employeesMap[email] || { firstName: '', lastName: '' };
                    let dia = '-';
                    if (entry?.fecha) {
                        const d = parseSpanishDate(entry.fecha);
                        dia = d ? dayFormatter.format(d) : '-';
                    }
                    let h = { diurnas: '-', nocturnas: '-', domDiurnas: '-', domNocturnas: '-', totalHHMM: '-' };
                    let lunchApplied = 'No';
                    if (entry && exit) {
                        const calc = calculateLaborHours(parseStringDate(entry.fecha, entry.hora), parseStringDate(exit.fecha, exit.hora), timeConfig);
                        if (!calc.error) {
                            h = calc.format;
                            if (calc.appliedLunchDeduction) lunchApplied = `Sí (${(timeConfig.calc_lunchMins || 60) / 60}h)`;
                        }
                    }
                    return [
                        email, emp.firstName, emp.lastName, dia,
                        entry?.fecha || '-', entry?.hora || '-', exit?.fecha || '-', exit?.hora || '-',
                        lunchApplied, h.diurnas, h.nocturnas, h.domDiurnas, h.domNocturnas, h.totalHHMM
                    ];
                });
            } else {
                // Resumen
                headers = ['Usuario', 'Nombres', 'Apellidos', 'Diu', 'Noc', 'Dom Diu', 'Dom Noc', 'Total'];
                const summary = {};
                shifts.forEach(({ entry, exit, email }) => {
                    if (!summary[email]) summary[email] = { u: email, fn: employeesMap[email]?.firstName || '', ln: employeesMap[email]?.lastName || '', d: 0, n: 0, dd: 0, dn: 0 };
                    if (entry && exit) {
                        const calc = calculateLaborHours(parseStringDate(entry.fecha, entry.hora), parseStringDate(exit.fecha, exit.hora), timeConfig);
                        if (!calc.error) {
                            summary[email].d += calc.raw.diurnas;
                            summary[email].n += calc.raw.nocturnas;
                            summary[email].dd += calc.raw.domDiurnas;
                            summary[email].dn += calc.raw.domNocturnas;
                        }
                    }
                });
                rows = Object.values(summary).map(s => [
                    s.u, s.fn, s.ln, (s.d / 60).toFixed(2), (s.n / 60).toFixed(2), (s.dd / 60).toFixed(2), (s.dn / 60).toFixed(2), ((s.d + s.n + s.dd + s.dn) / 60).toFixed(2)
                ]);
            }

            const ts = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
            if (exportFormatAttendance === 'xlsx') {
                exportToExcelHTML(`turnos_${ts}.xlsx`, headers, rows);
            } else {
                const escape = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
                const csvContent = '\ufeff' + [headers.join(','), ...rows.map(r => r.map(escape).join(','))].join('\n');
                const link = document.createElement('a');
                link.href = URL.createObjectURL(new Blob([csvContent], { type: 'text/csv;charset=utf-8;' }));
                link.download = `turnos_${ts}.csv`;
                link.click();
            }
        } catch (error) {
            console.error(error);
            alert('Error al exportar.');
        } finally {
            setExporting(false);
        }
    };

    const exportIncidentsToCSV = async () => {
        setExportingIncidents(true);
        try {
            const snap = await getDocs(query(collection(db, 'incidents'), orderBy('timestamp', 'asc')));
            let incidents = snap.docs.map(d => ({ id: d.id, ...d.data() }));

            if (incidentStartDate || incidentEndDate) {
                incidents = incidents.filter(inc => {
                    const d = parseSpanishDate(inc.fecha);
                    if (!d) return false;
                    const t = d.getTime();
                    const start = incidentStartDate ? new Date(incidentStartDate + 'T00:00:00').getTime() : 0;
                    const end = incidentEndDate ? new Date(incidentEndDate + 'T23:59:59').getTime() : Infinity;
                    return t >= start && t <= end;
                });
            }
            if (incidentCsvUserFilter.trim()) {
                const needle = incidentCsvUserFilter.trim().toLowerCase();
                incidents = incidents.filter(inc => (inc.usuario || '').toLowerCase().includes(needle));
            }
            if (incidents.length === 0) { alert('No hay novedades.'); return; }

            const headers = ['Usuario', 'Fecha', 'Hora', 'Localidad', 'Descripcion'];
            const rows = incidents.map(inc => [inc.usuario || '', inc.fecha || '', inc.hora || '', inc.localidad || '', inc.descripcion || '']);
            const ts = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
            if (exportFormatIncidents === 'xlsx') {
                exportToExcelHTML(`novedades_${ts}.xlsx`, headers, rows);
            } else {
                const escape = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
                const csvContent = '\ufeff' + [headers.join(','), ...rows.map(r => r.map(escape).join(','))].join('\n');
                const link = document.createElement('a');
                link.href = URL.createObjectURL(new Blob([csvContent], { type: 'text/csv;charset=utf-8;' }));
                link.download = `novedades_${ts}.csv`;
                link.click();
            }
        } catch (error) {
            console.error(error);
            alert('Error al exportar novedades.');
        } finally {
            setExportingIncidents(false);
        }
    };

    if (loading && !storageConfig) {
        return <div className="min-h-screen flex items-center justify-center"><Loader2 size={40} className="animate-spin text-blue-600" /></div>;
    }

    return (
        <div className="min-h-screen bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B] p-6">
            <div className="max-w-6xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2">
                        <FileText size={30} className="text-blue-600" />
                        Centro de Informes y Reportes
                        <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-mono ml-2 border border-gray-200">v{import.meta.env.VITE_APP_VERSION}</span>
                    </h1>
                    <button onClick={() => navigate('/dashboard')} className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 transition">Volver</button>
                </div>

                {/* 1. EXPORTAR FOTOS / EVIDENCIAS */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-blue-500">
                    <div className="flex justify-between items-start mb-4">
                        <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                            <Image size={24} className="text-blue-600" /> Evidencias Fotográficas
                        </h2>
                        {storageConfig && (storageConfig.saveAsistencia || storageConfig.saveIncidentes) && (
                            <button onClick={handleManualCleanup} disabled={cleaningStorage} className="text-xs bg-red-50 text-red-600 px-3 py-1.5 rounded-lg border border-red-200 hover:bg-red-100 font-bold flex items-center gap-1">
                                {cleaningStorage ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />} Limpiar Fotos Antiguas
                            </button>
                        )}
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4 items-end">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Fecha Inicio</label>
                            <input type="date" value={photoDesde} onChange={e => setPhotoDesde(e.target.value)} className="w-full px-4 py-2 border rounded-lg" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Fecha Fin</label>
                            <input type="date" value={photoHasta} onChange={e => setPhotoHasta(e.target.value)} className="w-full px-4 py-2 border rounded-lg" />
                        </div>
                        <button
                            disabled={photoSearching || !photoDesde || !photoHasta}
                            onClick={async () => {
                                setPhotoSearching(true); setPhotoMsg('Buscando...'); setPhotoProgress({ current: 0, total: 0 });
                                try {
                                    const lista = await listPhotosByFilter({ tipo: photoTipo, desde: new Date(photoDesde + 'T00:00:00'), hasta: new Date(photoHasta + 'T23:59:59'), filtroUsuario: photoFiltroUser });
                                    if (lista.length === 0) { setPhotoMsg('No se encontraron fotos.'); return; }
                                    setPhotoMsg(`Descargando ${lista.length} fotos...`);
                                    const { zipBlob, addedCount } = await downloadPhotosAsZip(lista, (c, t) => setPhotoProgress({ current: c, total: t }));
                                    const link = document.createElement('a'); link.href = URL.createObjectURL(zipBlob); link.download = `fotos_${photoDesde}_${photoHasta}.zip`; link.click();
                                    setPhotoMsg(`✅ Descargadas ${addedCount} fotos.`);
                                } catch (e) { setPhotoMsg('❌ Error: ' + e.message); } finally { setPhotoSearching(false); }
                            }}
                            className="w-full py-2 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 flex items-center justify-center gap-2"
                        >
                            {photoSearching ? <Loader2 size={20} className="animate-spin" /> : <Download size={20} />} Descargar Fotos
                        </button>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <select value={photoTipo} onChange={e => setPhotoTipo(e.target.value)} className="w-full px-4 py-2 border rounded-lg">
                            <option value="ambos">Todo (Asistencia + Novedades)</option>
                            <option value="asistencia">Solo Asistencia</option>
                            <option value="incidentes">Solo Novedades</option>
                        </select>
                        <input type="text" placeholder="Correo o dominio (opcional)" value={photoFiltroUser} onChange={e => setPhotoFiltroUser(e.target.value)} className="w-full px-4 py-2 border rounded-lg" />
                    </div>
                    {photoSearching && photoProgress.total > 0 && (
                        <div className="mt-4"><div className="w-full bg-gray-100 h-2 rounded-full overflow-hidden"><div className="bg-blue-600 h-full transition-all" style={{ width: `${(photoProgress.current / photoProgress.total) * 100}%` }}></div></div><p className="text-xs text-gray-500 mt-1">Progreso: {photoProgress.current} / {photoProgress.total}</p></div>
                    )}
                    <p className="text-sm text-gray-500 mt-2">{photoMsg}</p>
                </div>

                {/* 2. EXPORTAR ASISTENCIA */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-green-500">
                    <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2"><Download size={24} className="text-green-600" /> Reportes de Asistencia</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                        <div><label className="text-sm">Desde</label><input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <div><label className="text-sm">Hasta</label><input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <div><label className="text-sm">Filtro Usuario</label><input type="text" value={csvUserFilter} onChange={e => setCsvUserFilter(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                    </div>
                    <div className="flex gap-4 flex-wrap">
                        <select value={attendanceReportType} onChange={e => setAttendanceReportType(e.target.value)} className="flex-1 px-4 py-2 border rounded-lg min-w-[200px]">
                            <option value="estandar">Detallado Estándar</option>
                            <option value="detallado_horas">Discriminado por tipos de horas (Colombia)</option>
                            <option value="resumen">Resumen General por Empleado</option>
                        </select>
                        <select value={exportFormatAttendance} onChange={e => setExportFormatAttendance(e.target.value)} className="px-4 py-2 border rounded-lg">
                            <option value="csv">CSV</option>
                            <option value="xlsx">Excel</option>
                        </select>
                        <button onClick={exportToCSV} disabled={exporting} className="px-8 py-2 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 flex items-center gap-2 shadow-md">
                            {exporting ? <Loader2 size={20} className="animate-spin" /> : <FileText size={20} />} Generar Reporte
                        </button>
                    </div>

                    <div className="mt-8 pt-6 border-t border-red-50 flex items-center justify-between">
                        <div><h3 className="text-red-700 font-bold text-sm">Limpieza de Historial</h3><p className="text-xs text-gray-500">Borra definitivamente los registros en el rango de fechas seleccionado.</p></div>
                        <button onClick={handleBulkDelete} disabled={deleting || !startDate || !endDate} className="px-4 py-2 bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition">
                            {deleting ? 'Borrando...' : 'Borrar Rango'}
                        </button>
                    </div>
                </div>

                {/* 3. EXPORTAR NOVEDADES */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-6 border-l-4 border-orange-400">
                    <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2"><TriangleAlert size={24} className="text-orange-500" /> Reporte de Novedades</h2>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end mb-4">
                        <div className="md:col-span-1"><label className="text-sm">Desde</label><input type="date" value={incidentStartDate} onChange={e => setIncidentStartDate(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <div className="md:col-span-1"><label className="text-sm">Hasta</label><input type="date" value={incidentEndDate} onChange={e => setIncidentEndDate(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <div className="md:col-span-1"><label className="text-sm">Usuario</label><input type="text" value={incidentCsvUserFilter} onChange={e => setIncidentCsvUserFilter(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <div className="flex gap-2">
                            <select value={exportFormatIncidents} onChange={e => setExportFormatIncidents(e.target.value)} className="border rounded-lg px-2"><option value="csv">CSV</option><option value="xlsx">XLSX</option></select>
                            <button onClick={exportIncidentsToCSV} disabled={exportingIncidents} className="flex-1 bg-orange-600 text-white py-2 rounded-lg font-bold hover:bg-orange-700 flex justify-center gap-2">
                                {exportingIncidents ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />} Exportar
                            </button>
                        </div>
                    </div>
                    <div className="mt-4 pt-4 border-t border-red-50 flex items-center justify-between">
                        <p className="text-xs text-gray-500">Borrar novedades permanentemente en el rango de fechas.</p>
                        <button onClick={handleBulkDeleteIncidents} disabled={deletingIncidents || !incidentStartDate || !incidentEndDate} className="px-4 py-2 bg-red-100 text-red-700 rounded-lg font-bold hover:bg-red-200 transition">Borrar Rango</button>
                    </div>
                </div>

                {/* 4. GESTIÓN DE EMPLEADOS */}
                <div className="bg-white rounded-xl shadow-2xl p-6 mb-12 border-l-4 border-emerald-500">
                    <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2"><UserMinus size={24} className="text-emerald-600" /> Personal y Empleados</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">
                        <div className="md:col-span-1"><input type="text" placeholder="Filtrar por email..." value={filterEmail} onChange={e => setFilterEmail(e.target.value)} className="w-full px-4 py-2 border rounded-lg" /></div>
                        <button onClick={exportEmployeesToCSV} disabled={exportingEmployees} className="bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 flex justify-center gap-2 shadow-sm">
                            {exportingEmployees ? <Loader2 size={18} className="animate-spin" /> : <FileText size={18} />} Exportar Personal
                        </button>
                        <button onClick={() => setShowDeleteModal(true)} className="bg-red-600 text-white py-2 rounded-lg font-bold hover:bg-red-700 flex justify-center gap-2 shadow-sm">
                            <Trash2 size={18} /> Borrar Empleado
                        </button>
                    </div>
                </div>
            </div>

            <DeleteEmployeeModal isOpen={showDeleteModal} onClose={() => setShowDeleteModal(false)} />
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { collection, addDoc, serverTimestamp, getDocs, query, where, doc, getDoc } from 'firebase/firestore';
import { createUserWithEmailAndPassword } from 'firebase/auth';
import { httpsCallable } from 'firebase/functions';
import { auth, db, functions } from '../firebaseConfig';
import { fetchLicenseStatus } from '../services/licenseService';
import { UserPlus, LogOut, Loader2, Camera, UserCheck } from 'lucide-react';
import * as faceapi from '@vladmandic/face-api';

// ─── Definición de campos opcionales (igual que en Configuracion.jsx) ─────────
const FIELD_DEFS = [
    // Identificación Básica
    { key: 'documentoIdentidad', label: 'Documento de identidad', type: 'text', group: 'Identificación' },
    { key: 'fechaNacimiento', label: 'Fecha de nacimiento', type: 'date', group: 'Identificación' },
    { key: 'fechaIngreso', label: 'Fecha de ingreso', type: 'date', group: 'Identificación' },
    { key: 'infoBancaria', label: 'Información bancaria', type: 'text', group: 'Identificación' },
    { key: 'licenciaConducir', label: 'Licencia de conducir', type: 'text', group: 'Identificación' },
    { key: 'tallaUniforme', label: 'Talla de uniformes', type: 'text', group: 'Identificación' },
    { key: 'tallaCalzado', label: 'Talla de calzado', type: 'text', group: 'Identificación' },
    { key: 'alergias', label: 'Alergias / cond. médicas', type: 'text', group: 'Identificación' },
    { key: 'estadoCivil', label: 'Estado civil', type: 'text', group: 'Identificación' },
    { key: 'hijos', label: 'Hijos y edades', type: 'text', group: 'Identificación' },
    { key: 'grupoSanguineo', label: 'Grupo sanguíneo', type: 'text', group: 'Identificación' },
    { key: 'eps', label: 'EPS', type: 'text', group: 'Identificación' },
    { key: 'arl', label: 'ARL', type: 'text', group: 'Identificación' },
    // Contacto
    { key: 'direccion', label: 'Dirección de residencia', type: 'text', group: 'Contacto' },
    { key: 'telefono', label: 'Teléfono personal', type: 'tel', group: 'Contacto' },
    { key: 'correoPersonal', label: 'Correo electrónico personal', type: 'email', group: 'Contacto' },
    { key: 'contactoEmergencia', label: 'Contacto de emergencia', type: 'text', group: 'Contacto' },
    // Formación
    { key: 'nivelEducativo', label: 'Nivel educativo', type: 'text', group: 'Formación' },
    { key: 'idiomas', label: 'Idiomas y nivel', type: 'text', group: 'Formación' },
];

const GROUP_COLORS = {
    'Identificación': 'border-blue-400',
    'Contacto': 'border-green-400',
    'Formación': 'border-purple-400',
};

export default function Register() {
    // ─── Estado campos fijos ──────────────────────────────────────────────────
    const [email, setEmail] = useState('');
    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [faceDescriptor, setFaceDescriptor] = useState(null);
    const [isCameraOpen, setIsCameraOpen] = useState(false);
    const [modelsLoaded, setModelsLoaded] = useState(false);
    const [capturingFace, setCapturingFace] = useState(false);
    const videoRef = React.useRef(null);
    const canvasRef = React.useRef(null);
    const streamRef = React.useRef(null);
    const [configLoading, setConfigLoading] = useState(true);

    // ─── Estado campos opcionales dinámicos ───────────────────────────────────
    const [fieldConfig, setFieldConfig] = useState({});        // qué campos están activos
    const [extraFields, setExtraFields] = useState({});        // valores de los campos activos
    // ─── Estado de la Licencia ────────────────────────────────────────────────
    const [licenseInfo, setLicenseInfo] = useState(null);
    const [employeeCount, setEmployeeCount] = useState(0);

    const navigate = useNavigate();
    const { adminAccess } = useAuth();

    // ─── Cargar configuración de campos y estado de Licencia ─────────────────
    useEffect(() => {
        const loadInitialData = async () => {
            try {
                const snap = await getDoc(doc(db, 'settings', 'employeeFields'));
                if (snap.exists()) {
                    setFieldConfig(snap.data());
                }

                // Cargar Licencia y contar empleados actuales (Auth)
                const lic = await fetchLicenseStatus();
                setLicenseInfo(lic);

                const getUsersListFn = httpsCallable(functions, 'getUsersList');
                try {
                    const result = await getUsersListFn();
                    if (result.data && result.data.users) {
                        setEmployeeCount(result.data.users.length);
                    }
                } catch (fnErr) {
                    console.error("Error al obtener la lista de usuarios:", fnErr);
                }

            } catch (err) {
                console.warn('Error cargando iniciales:', err);
            } finally {
                setConfigLoading(false);
            }
        };
        loadInitialData();
    }, []);

    // ─── Cargar modelos de reconocimiento facial ──────────────────────────────
    useEffect(() => {
        const loadModels = async () => {
            try {
                if (faceapi.nets.tinyFaceDetector.isLoaded &&
                    faceapi.nets.faceLandmark68Net.isLoaded &&
                    faceapi.nets.faceRecognitionNet.isLoaded) {
                    setModelsLoaded(true);
                    return;
                }
                const MODEL_URL = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/model/';
                await Promise.all([
                    faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),
                    faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL),
                    faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL)
                ]);
                setModelsLoaded(true);
            } catch (err) {
                console.error('Error al cargar modelos de cara:', err);
                setError('No se pudieron cargar los modelos de reconocimiento facial.');
            }
        };
        loadModels();
    }, []);

    useEffect(() => {
        if (!adminAccess['/registro']) navigate('/login');
    }, [adminAccess, navigate]);

    // ─── Cámara ───────────────────────────────────────────────────────────────
    const startCamera = async () => {
        setError('');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
            streamRef.current = stream;
            setIsCameraOpen(true);
        } catch (err) {
            console.error('Error al acceder a la cámara:', err);
            setError('No se pudo acceder a la cámara. Asegúrate de dar permisos.');
        }
    };

    useEffect(() => {
        if (isCameraOpen && videoRef.current && streamRef.current) {
            videoRef.current.srcObject = streamRef.current;
        }
    }, [isCameraOpen]);

    const stopCamera = () => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
        setIsCameraOpen(false);
    };

    const captureFace = async () => {
        if (!videoRef.current) return;
        setCapturingFace(true);
        setError('');
        try {
            const detection = await faceapi
                .detectSingleFace(videoRef.current, new faceapi.TinyFaceDetectorOptions())
                .withFaceLandmarks()
                .withFaceDescriptor();
            if (!detection) {
                setError('No se detectó ningún rostro. Asegúrate de que la cara esté bien iluminada y visible.');
            } else {
                setFaceDescriptor(Array.from(detection.descriptor));
                stopCamera();
            }
        } catch (err) {
            console.error('Error capturando rostro:', err);
            setError('Error al analizar el rostro. Intenta de nuevo.');
        } finally {
            setCapturingFace(false);
        }
    };

    // ─── Submit ───────────────────────────────────────────────────────────────
    const handleSubmit = async (e) => {
        e.preventDefault();

        // --- Validación local del Token Licencia ---
        if (!licenseInfo?.decoded?.isValid) return setError("Licencia no encontrada o corrupta. Revise Configuraciones.");
        if (licenseInfo.decoded.isExpired) return setError(`Licencia expirada. Contacte a ${licenseInfo.decoded.providerName}.`);
        if (employeeCount >= licenseInfo.decoded.absoluteMaxEmployees) return setError(`Límite bloqueado (${employeeCount}/${licenseInfo.decoded.absoluteMaxEmployees}). Comuníquese con el administrador para ampliar el plan.`);

        if (password !== confirmPassword) return setError('Las contraseñas no coinciden');
        if (!faceDescriptor) return setError('Debes capturar el rostro del empleado antes de crear la cuenta.');

        try {
            setError('');
            setLoading(true);
            let emailToUse = email.includes('@') ? email : `${email}@usuario.com`;
            emailToUse = emailToUse.toLowerCase().trim();

            // Construir objeto con campos opcionales activos
            const optionalData = {};
            FIELD_DEFS.forEach(({ key }) => {
                if (fieldConfig[key] && extraFields[key] !== undefined) {
                    optionalData[key] = extraFields[key];
                }
            });

            // Reemplazo: Delegamos la creación al "Policía" del Back-End (Cloud Function)
            // para que valide los cupos de la licencia antes de tocar Authentication
            const createEmployeeSecureFn = httpsCallable(functions, 'createEmployeeSecure');
            const result = await createEmployeeSecureFn({
                email: emailToUse,
                password: password,
                firstName: firstName.trim(),
                lastName: lastName.trim(),
                faceDescriptor: faceDescriptor,
                extraFields: optionalData
            });

            if (result.data && result.data.success) {
                alert('Usuario creado exitosamente.');
                setEmail(''); setFirstName(''); setLastName('');
                setPassword(''); setConfirmPassword('');
                setFaceDescriptor(null);
                setExtraFields({});
                setEmployeeCount(prev => prev + 1); // Aumentar en UI
            } else {
                setError('Error desconocido al crear la cuenta.');
            }

        } catch (err) {
            console.error(err);
            // Capturar errores amigables lanzados por la Cloud Function
            if (err.code === 'functions/resource-exhausted') {
                setError(err.message || "Límite absoluto de empleados alcanzado. Licencia Agotada.");
            } else if (err.code === 'functions/permission-denied') {
                setError(err.message || "Licencia corrupta o caducada. Verifique Configuraciones.");
            } else if (err.code === 'functions/already-exists') {
                setError('Este correo ya pertenece a otro usuario registrado.');
            } else {
                // Posibles errores de Auth o validaciones
                setError('Error al crear cuenta: ' + (err.message || err));
            }
        }
        setLoading(false);
    };

    // ─── Campos opcionales activos agrupados ──────────────────────────────────
    const activeGroups = (() => {
        const groups = {};
        FIELD_DEFS.forEach(f => {
            if (fieldConfig[f.key]) {
                if (!groups[f.group]) groups[f.group] = [];
                groups[f.group].push(f);
            }
        });
        return groups;
    })();

    const hasOptionalFields = Object.keys(activeGroups).length > 0;

    // ─── Banderas de Bloqueo por Licencia ────────────────────────────────────
    const isLicenseExpired = licenseInfo?.decoded?.isExpired;
    const isWarningZone = licenseInfo?.decoded && (employeeCount >= licenseInfo.decoded.maxEmployees) && (employeeCount < licenseInfo.decoded.absoluteMaxEmployees);
    const isLicenseFull = licenseInfo?.decoded && (employeeCount >= licenseInfo.decoded.absoluteMaxEmployees);
    const blockCreation = isLicenseExpired || isLicenseFull || !licenseInfo?.decoded?.isValid;

    // ─── Render ───────────────────────────────────────────────────────────────
    return (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-b from-[#3C7DA6] to-[#6FAF6B] p-4">
            <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-lg backdrop-blur-sm bg-opacity-90">
                <div className="flex justify-center mb-4">
                    <div className="bg-green-100 p-3 rounded-full">
                        <UserPlus className="text-green-600" size={32} />
                    </div>
                </div>
                <h2 className="text-3xl font-bold text-center mb-6 text-gray-800 flex items-center justify-center gap-2">
                    Registrar Nuevo Empleado
                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-mono border border-gray-200">v{import.meta.env.VITE_APP_VERSION}</span>
                </h2>

                {/* Panel Informativo Licencia */}
                {licenseInfo?.decoded && (
